-- ---------- functions ----------
CREATE OR REPLACE FUNCTION public.accept_teacher_center_invite(p_teacher_user_id uuid, p_center_id uuid)
 RETURNS teacher_center
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_tc public.teacher_center;
begin
  select * into v_tc from public.teacher_center
   where teacher_id=p_teacher_user_id and center_id=p_center_id for update;
  if not found then raise exception 'no invite for teacher % at center %', p_teacher_user_id, p_center_id using errcode='P0002'; end if;
  if v_tc.status = 'active' then return v_tc; end if;
  if v_tc.status <> 'pending' then
    raise exception 'cannot accept invite in status %', v_tc.status using errcode='23514'; end if;

  update public.teacher_center set status='active', accepted_at=now() where id=v_tc.id returning * into v_tc;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values ('teacher_center_accepted','teacher_center', v_tc.id, p_teacher_user_id, p_center_id,
          jsonb_build_object('teacher_id', p_teacher_user_id));
  return v_tc;
end; $function$
;
CREATE OR REPLACE FUNCTION public.ai_execute_query(p_sql text, p_center_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
BEGIN
  EXECUTE format('SELECT COALESCE(jsonb_agg(to_jsonb(sub)), ''[]''::jsonb) FROM (%s) sub', p_sql)
  USING p_center_id
  INTO result;
  RETURN result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.append_commission_pause(p_center_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE commissions
  SET clock_pause_log = clock_pause_log || jsonb_build_array(
    jsonb_build_object('paused_at', now()::text, 'resumed_at', null)
  )
  WHERE center_id = p_center_id
    AND t2_status IN ('locked', 'eligible')
    AND (
      jsonb_array_length(clock_pause_log) = 0
      OR (clock_pause_log -> -1 ->> 'resumed_at') IS NOT NULL
    );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_center_subscription_transition(p_subscription_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS subscriptions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sub        public.subscriptions;
  v_old_status text;
begin
  select * into v_sub from public.subscriptions where id = p_subscription_id for update;
  if not found then
    raise exception 'subscription % not found', p_subscription_id using errcode = 'P0002';
  end if;

  v_old_status := v_sub.status;

  if p_new_status not in ('active','past_due','suspended','cancelled') then
    raise exception 'invalid subscription status %', p_new_status using errcode = '23514';
  end if;

  if v_old_status = p_new_status then
    return v_sub;
  end if;

  if not (
        (v_old_status = 'active'    and p_new_status in ('past_due','suspended','cancelled'))
     or (v_old_status = 'past_due'  and p_new_status in ('active','suspended','cancelled'))
     or (v_old_status = 'suspended' and p_new_status in ('active','cancelled'))
     or (v_old_status = 'cancelled' and p_new_status = 'active')
  ) then
    raise exception 'illegal subscription transition: % -> %', v_old_status, p_new_status
      using errcode = '23514';
  end if;

  update public.subscriptions
     set status     = p_new_status,
         updated_at = now()
   where id = p_subscription_id
   returning * into v_sub;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values (
    'center_subscription_transition',
    'subscription',
    v_sub.id,
    p_actor_id,
    v_sub.center_id,
    jsonb_build_object('from', v_old_status, 'to', p_new_status)
  );

  return v_sub;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_chargeback_transition(p_chargeback_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS chargebacks
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cb         public.chargebacks;
  v_old_status text;
begin
  select * into v_cb from public.chargebacks where id = p_chargeback_id for update;
  if not found then
    raise exception 'chargeback % not found', p_chargeback_id using errcode = 'P0002';
  end if;

  v_old_status := v_cb.status;

  if p_new_status not in ('opened','won','lost') then
    raise exception 'invalid chargeback status %', p_new_status using errcode = '23514';
  end if;

  if v_old_status = p_new_status then
    return v_cb;
  end if;

  if not (v_old_status = 'opened' and p_new_status in ('won','lost')) then
    raise exception 'illegal chargeback transition: % -> %', v_old_status, p_new_status
      using errcode = '23514';
  end if;

  update public.chargebacks
     set status      = p_new_status,
         resolved_at = now()
   where id = p_chargeback_id
   returning * into v_cb;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values (
    'chargeback_transition',
    'chargeback',
    v_cb.id,
    p_actor_id,
    v_cb.center_id,
    jsonb_build_object('from', v_old_status, 'to', p_new_status, 'transaction_id', v_cb.transaction_id)
  );

  return v_cb;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_enrollment_transition(p_enrollment_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS enrollments
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_enr public.enrollments; v_old_status text; v_center_id uuid;
begin
  select * into v_enr from public.enrollments where id=p_enrollment_id for update;
  if not found then raise exception 'enrollment % not found', p_enrollment_id using errcode='P0002'; end if;
  v_old_status:=v_enr.status;
  if p_new_status not in ('pending','active','rejected','removed') then raise exception 'invalid enrollment status %', p_new_status using errcode='23514'; end if;
  if v_old_status=p_new_status then return v_enr; end if;
  if not ((v_old_status='pending' and p_new_status in ('active','rejected','removed'))
       or (v_old_status='active' and p_new_status='removed')) then
    raise exception 'illegal enrollment transition: % -> %', v_old_status, p_new_status using errcode='23514'; end if;
  set local app.allow_lifecycle_write='on';
  update public.enrollments set status=p_new_status,
    approved_by=case when p_new_status in ('active','rejected') then coalesce(p_actor_id,approved_by) else approved_by end,
    joined_at=case when p_new_status='active' and joined_at is null then now() else joined_at end
   where id=p_enrollment_id returning * into v_enr;
  set local app.allow_lifecycle_write='off';
  select sg.center_id into v_center_id from public.student_groups sg where sg.id=v_enr.group_id;
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('enrollment_transition','enrollment',v_enr.id,p_actor_id,v_center_id,
          jsonb_build_object('from',v_old_status,'to',p_new_status));
  return v_enr;
end; $function$
;
CREATE OR REPLACE FUNCTION public.apply_session_transition(p_session_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS sessions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sess public.sessions; v_old_status text; v_center_id uuid;
begin
  select * into v_sess from public.sessions where id=p_session_id for update;
  if not found then raise exception 'session % not found', p_session_id using errcode='P0002'; end if;
  v_old_status:=v_sess.status;
  if p_new_status not in ('scheduled','live','finished','cancelled') then raise exception 'invalid session status %', p_new_status using errcode='23514'; end if;
  if v_old_status=p_new_status then return v_sess; end if;
  if not ((v_old_status='scheduled' and p_new_status in ('live','finished','cancelled'))
       or (v_old_status='live' and p_new_status in ('finished','cancelled'))) then
    raise exception 'illegal session transition: % -> %', v_old_status, p_new_status using errcode='23514'; end if;
  set local app.allow_lifecycle_write='on';
  update public.sessions set status=p_new_status,
    finished_at=case when p_new_status='finished' and finished_at is null then now() else finished_at end
   where id=p_session_id returning * into v_sess;
  set local app.allow_lifecycle_write='off';
  select sg.center_id into v_center_id from public.student_groups sg where sg.id=v_sess.group_id;
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('session_transition','session',v_sess.id,p_actor_id,v_center_id,
          jsonb_build_object('from',v_old_status,'to',p_new_status));
  return v_sess;
end; $function$
;
CREATE OR REPLACE FUNCTION public.apply_student_credits(p_student_id uuid, p_teacher_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(credits_applied integer, amount_applied numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_outstanding numeric;
  v_oldest_txn  uuid;
  v_credit      record;
  v_count       int := 0;
  v_applied     numeric := 0;
begin
  -- Outstanding = sum of this student's pending lesson bills for this teacher.
  select coalesce(sum(t.amount_billed), 0) into v_outstanding
  from public.transactions t
  where t.student_id = p_student_id
    and t.teacher_id = p_teacher_id
    and t.kind = 'lesson'
    and t.status = 'pending';

  if v_outstanding <= 0 then
    return query select 0, 0::numeric;
    return;
  end if;

  -- Oldest open pending lesson txn, for applied_to_transaction_id traceability.
  select t.id into v_oldest_txn
  from public.transactions t
  where t.student_id = p_student_id
    and t.teacher_id = p_teacher_id
    and t.kind = 'lesson'
    and t.status = 'pending'
  order by t.created_at asc
  limit 1;

  -- Walk active credits oldest-first, lock them.
  for v_credit in
    select sc.id, sc.amount
    from public.student_credits sc
    where sc.student_id = p_student_id
      and sc.teacher_id = p_teacher_id
      and sc.status = 'active'
    order by sc.created_at asc
    for update
  loop
    -- Model X: apply a credit only if it fits whole within remaining outstanding.
    if v_credit.amount <= v_outstanding then
      update public.student_credits
      set status = 'applied',
          applied_to_transaction_id = v_oldest_txn
      where id = v_credit.id;

      v_outstanding := v_outstanding - v_credit.amount;
      v_applied := v_applied + v_credit.amount;
      v_count := v_count + 1;

      if v_outstanding <= 0 then
        exit;
      end if;
    end if;
    -- Overflowing credit is left active (carried forward whole).
  end loop;

  if v_count > 0 then
    insert into public.audit_log (action, entity_type, entity_id, user_id, details)
    values (
      'credits_applied', 'student', p_student_id, p_actor_id,
      jsonb_build_object('teacher_id', p_teacher_id, 'credits_applied', v_count,
                         'amount_applied', v_applied, 'applied_to_transaction_id', v_oldest_txn)
    );
  end if;

  return query select v_count, v_applied;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_teacher_subscription_transition(p_subscription_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS teacher_subscriptions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sub public.teacher_subscriptions; v_old_status text;
begin
  select * into v_sub from public.teacher_subscriptions where id=p_subscription_id for update;
  if not found then raise exception 'teacher subscription % not found', p_subscription_id using errcode='P0002'; end if;
  v_old_status:=v_sub.status;
  if p_new_status not in ('trialing','active','past_due','suspended','cancelled') then raise exception 'invalid teacher subscription status %', p_new_status using errcode='23514'; end if;
  if v_old_status=p_new_status then return v_sub; end if;
  if not ((v_old_status='trialing' and p_new_status in ('active','past_due','cancelled'))
       or (v_old_status='active' and p_new_status in ('past_due','suspended','cancelled'))
       or (v_old_status='past_due' and p_new_status in ('active','suspended','cancelled'))
       or (v_old_status='suspended' and p_new_status in ('active','cancelled'))
       or (v_old_status='cancelled' and p_new_status='active')) then
    raise exception 'illegal teacher subscription transition: % -> %', v_old_status, p_new_status using errcode='23514'; end if;
  set local app.allow_lifecycle_write='on';
  update public.teacher_subscriptions set status=p_new_status where id=p_subscription_id returning * into v_sub;
  set local app.allow_lifecycle_write='off';
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('teacher_subscription_transition','teacher_subscription',v_sub.id,p_actor_id,null,
          jsonb_build_object('from',v_old_status,'to',p_new_status,'teacher_id',v_sub.teacher_id));
  return v_sub;
end; $function$
;
CREATE OR REPLACE FUNCTION public.apply_transaction_transition(p_transaction_id uuid, p_new_status text, p_actor_id uuid DEFAULT NULL::uuid, p_method text DEFAULT NULL::text)
 RETURNS transactions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_txn public.transactions; v_old_status text; v_method text;
begin
  select * into v_txn from public.transactions where id=p_transaction_id for update;
  if not found then raise exception 'transaction % not found', p_transaction_id using errcode='P0002'; end if;
  v_old_status:=v_txn.status;
  if p_new_status not in ('pending','paid','failed','cancelled') then raise exception 'invalid transaction status %', p_new_status using errcode='23514'; end if;
  if p_method is not null and p_method not in ('card','wallet','apple_pay','google_pay','instapay','cash','vodafone_cash','other') then
    raise exception 'invalid payment method %', p_method using errcode='23514'; end if;
  if v_txn.method is not null and p_method is not null and p_method <> v_txn.method then
    raise exception 'method already set to % and cannot be changed', v_txn.method using errcode='23514'; end if;
  if v_old_status=p_new_status then return v_txn; end if;
  if not (v_old_status='pending' and p_new_status in ('paid','failed','cancelled')) then
    raise exception 'illegal transaction transition: % -> %', v_old_status, p_new_status using errcode='23514'; end if;
  v_method := coalesce(v_txn.method, p_method);
  if p_new_status='paid' and v_method is null then
    raise exception 'method required when marking paid' using errcode='23514'; end if;
  set local app.allow_lifecycle_write='on';
  update public.transactions set status=p_new_status,
    method=v_method,
    paid_at=case when p_new_status='paid' and paid_at is null then now() else paid_at end,
    marked_paid_by=case when p_new_status='paid' then coalesce(p_actor_id,marked_paid_by) else marked_paid_by end
   where id=p_transaction_id returning * into v_txn;
  set local app.allow_lifecycle_write='off';
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('transaction_transition','transaction',v_txn.id,p_actor_id,v_txn.center_id,
          jsonb_build_object('from',v_old_status,'to',p_new_status,'is_test',v_txn.is_test,'method',v_method));
  return v_txn;
end; $function$
;
CREATE OR REPLACE FUNCTION public.approve_student_rpc(p_student_id uuid, p_center_id uuid, p_group_ids uuid[] DEFAULT ARRAY[]::uuid[], p_approved_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_student           RECORD;
  v_center            RECORD;
  v_new_student_count INTEGER;
  v_month_key         TEXT;
  v_group_id          UUID;
BEGIN
  SELECT * INTO v_student
  FROM students
  WHERE id = p_student_id
    AND center_id = p_center_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'student_not_found' USING ERRCODE = 'P0001';
  END IF;

  IF v_student.is_active = true THEN
    RAISE EXCEPTION 'student_already_active' USING ERRCODE = 'P0002';
  END IF;

  UPDATE students
  SET is_active = true
  WHERE id = p_student_id;

  IF array_length(p_group_ids, 1) > 0 THEN
    FOREACH v_group_id IN ARRAY p_group_ids
    LOOP
      INSERT INTO student_group_members (student_id, group_id)
      SELECT p_student_id, v_group_id
      WHERE EXISTS (
        SELECT 1 FROM student_groups
        WHERE id = v_group_id AND center_id = p_center_id
      )
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  v_month_key := to_char(NOW(), 'YYYY-MM');

  INSERT INTO parent_pack_monthly_counts (
    center_id, billing_period, student_id, parent_phone
  )
  SELECT
    p_center_id,
    v_month_key,
    s.id,
    s.parent_phone
  FROM students s
  WHERE s.center_id = p_center_id
    AND s.is_active = true
    AND s.parent_phone IS NOT NULL
    AND s.parent_phone != ''
  ON CONFLICT DO NOTHING;

  SELECT COUNT(*) INTO v_new_student_count
  FROM students
  WHERE center_id = p_center_id AND is_active = true;

  INSERT INTO center_metrics_daily (
    center_id, metric_date, students_active, last_upserted_at
  )
  VALUES (
    p_center_id, CURRENT_DATE, v_new_student_count, NOW()
  )
  ON CONFLICT (center_id, metric_date) DO UPDATE SET
    students_active  = EXCLUDED.students_active,
    last_upserted_at = NOW();

  RETURN jsonb_build_object(
    'success',            true,
    'student_id',         p_student_id,
    'new_student_count',  v_new_student_count
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_center_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  next_code INTEGER;
BEGIN
  SELECT COALESCE(MAX(center_code::INTEGER), 100) + 1
  INTO next_code
  FROM centers
  WHERE center_code ~ '^\d+$';

  IF next_code < 101 THEN
    next_code := 101;
  END IF;

  NEW.center_code := LPAD(next_code::TEXT, 3, '0');
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_student_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_center_code text;
  v_next_seq    integer;
begin
  if new.student_number is not null then
    return new;
  end if;

  -- Private (center-less) student: no center-scoped number. Leave null.
  if new.center_id is null then
    return new;
  end if;

  select student_sequence, center_code
  into   v_next_seq, v_center_code
  from   centers
  where  id = new.center_id
  for update;

  if v_center_code is null then
    raise exception 'assign_student_number: no center found for id %', new.center_id;
  end if;

  new.student_number := '#' || v_center_code || '-' || lpad(v_next_seq::text, 4, '0');

  update centers
  set    student_sequence = student_sequence + 1
  where  id = new.center_id;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_teacher_to_group(p_group_id uuid, p_teacher_user_id uuid, p_split_pct numeric, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS student_groups
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_group public.student_groups; 
begin
  select * into v_group from public.student_groups where id=p_group_id for update;
  if not found then raise exception 'group % not found', p_group_id using errcode='P0002'; end if;
  if v_group.kind <> 'center' then
    raise exception 'assign_teacher_to_group is for center groups; group % is %', p_group_id, v_group.kind using errcode='23514'; end if;
  if p_split_pct is null or p_split_pct < 0 or p_split_pct > 100 then
    raise exception 'invalid split pct %', p_split_pct using errcode='23514'; end if;
  if not exists (select 1 from public.teacher_center tc
                 where tc.teacher_id=p_teacher_user_id and tc.center_id=v_group.center_id and tc.status='active') then
    raise exception 'teacher % has no active relationship with center %', p_teacher_user_id, v_group.center_id using errcode='23514'; end if;

  update public.student_groups
    set teacher_id=p_teacher_user_id, teacher_split_pct=p_split_pct
    where id=p_group_id returning * into v_group;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values ('teacher_assigned_to_group','student_group', p_group_id, p_actor_id, v_group.center_id,
          jsonb_build_object('teacher_id', p_teacher_user_id, 'split_pct', p_split_pct));
  return v_group;
end; $function$
;
