 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE centers
  SET credit_reserved = GREATEST(0,
    COALESCE(credit_reserved, 0) - p_amount)
  WHERE id = p_center_id;
END;
