CREATE OR REPLACE FUNCTION public.chq_prevent_blast_tampering()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN RAISE EXCEPTION 'blasts: cannot modify total_amount'; END IF;
  IF NEW.base_amount IS DISTINCT FROM OLD.base_amount THEN RAISE EXCEPTION 'blasts: cannot modify base_amount'; END IF;
  IF NEW.service_fee IS DISTINCT FROM OLD.service_fee THEN RAISE EXCEPTION 'blasts: cannot modify service_fee'; END IF;
  IF NEW.vat IS DISTINCT FROM OLD.vat THEN RAISE EXCEPTION 'blasts: cannot modify vat'; END IF;
  IF NEW.billing_status IS DISTINCT FROM OLD.billing_status THEN RAISE EXCEPTION 'blasts: cannot modify billing_status'; END IF;
  IF NEW.charged_at IS DISTINCT FROM OLD.charged_at THEN RAISE EXCEPTION 'blasts: cannot modify charged_at'; END IF;
  IF NEW.parents_notified IS DISTINCT FROM OLD.parents_notified THEN RAISE EXCEPTION 'blasts: cannot modify parents_notified'; END IF;
  RETURN NEW;
END;
$function$
;
