  IF NEW.subscription_monthly_fee IS DISTINCT FROM OLD.subscription_monthly_fee THEN RAISE EXCEPTION 'centers: cannot modify subscription_monthly_fee'; END IF;
  IF NEW.pack_price_per_parent IS DISTINCT FROM OLD.pack_price_per_parent THEN RAISE EXCEPTION 'centers: cannot modify pack_price_per_parent'; END IF;
  IF NEW.billing_period IS DISTINCT FROM OLD.billing_period THEN RAISE EXCEPTION 'centers: cannot modify billing_period'; END IF;
  IF NEW.billing_type IS DISTINCT FROM OLD.billing_type THEN RAISE EXCEPTION 'centers: cannot modify billing_type'; END IF;
  IF NEW.billing_cycle_start IS DISTINCT FROM OLD.billing_cycle_start THEN RAISE EXCEPTION 'centers: cannot modify billing_cycle_start'; END IF;
  IF NEW.is_early_adopter IS DISTINCT FROM OLD.is_early_adopter THEN RAISE EXCEPTION 'centers: cannot modify is_early_adopter'; END IF;
  IF NEW.reactivation_fee_amount IS DISTINCT FROM OLD.reactivation_fee_amount THEN RAISE EXCEPTION 'centers: cannot modify reactivation_fee_amount'; END IF;
  IF NEW.suspended_at IS DISTINCT FROM OLD.suspended_at THEN RAISE EXCEPTION 'centers: cannot modify suspended_at'; END IF;
  IF NEW.auto_suspend_at IS DISTINCT FROM OLD.auto_suspend_at THEN RAISE EXCEPTION 'centers: cannot modify auto_suspend_at'; END IF;
  IF NEW.pack_pending_balance IS DISTINCT FROM OLD.pack_pending_balance THEN RAISE EXCEPTION 'centers: cannot modify pack_pending_balance'; END IF;
  IF NEW.announcement_cap IS DISTINCT FROM OLD.announcement_cap THEN RAISE EXCEPTION 'centers: cannot modify announcement_cap'; END IF;
  IF NEW.announcement_price_per_blast IS DISTINCT FROM OLD.announcement_price_per_blast THEN RAISE EXCEPTION 'centers: cannot modify announcement_price_per_blast'; END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chq_prevent_invoice_tampering()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(current_setting('app.allow_invoice_correction', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  IF NEW.owner_type IS DISTINCT FROM OLD.owner_type THEN
    RAISE EXCEPTION 'invoices: cannot modify owner_type';
  END IF;
  IF NEW.center_id IS DISTINCT FROM OLD.center_id THEN
    RAISE EXCEPTION 'invoices: cannot modify center_id';
  END IF;
  IF NEW.teacher_id IS DISTINCT FROM OLD.teacher_id THEN
    RAISE EXCEPTION 'invoices: cannot modify teacher_id';
  END IF;

  IF OLD.status = 'paid' THEN
    IF NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN
      RAISE EXCEPTION 'invoices: cannot modify total_amount of a paid invoice';
    END IF;
    IF NEW.amount_received IS DISTINCT FROM OLD.amount_received THEN
      RAISE EXCEPTION 'invoices: cannot modify amount_received of a paid invoice';
    END IF;
    IF NEW.paid_at IS DISTINCT FROM OLD.paid_at THEN
      RAISE EXCEPTION 'invoices: cannot modify paid_at of a paid invoice';
    END IF;
    IF NEW.invoice_type IS DISTINCT FROM OLD.invoice_type THEN
      RAISE EXCEPTION 'invoices: cannot modify invoice_type of a paid invoice';
    END IF;
    IF NEW.paymob_transaction_id IS DISTINCT FROM OLD.paymob_transaction_id THEN
      RAISE EXCEPTION 'invoices: cannot modify paymob_transaction_id of a paid invoice';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'chargeback' THEN
      RAISE EXCEPTION 'invoices: cannot change status of a paid invoice (except chargeback)';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chq_prevent_user_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.id = auth.uid() AND NEW.role IS DISTINCT FROM OLD.role THEN
    RAISE EXCEPTION 'users: cannot modify own role';
  END IF;
  IF NEW.id = auth.uid() AND NEW.center_id IS DISTINCT FROM OLD.center_id THEN
    RAISE EXCEPTION 'users: cannot modify own center_id';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.close_commission_pause(p_center_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log        JSONB;
  v_last_idx   INTEGER;
  v_last_entry JSONB;
  v_cid        UUID;
BEGIN
  FOR v_cid IN
    SELECT id FROM commissions
    WHERE center_id = p_center_id AND t2_status IN ('locked', 'eligible')
  LOOP
    SELECT clock_pause_log INTO v_log FROM commissions WHERE id = v_cid;
    IF v_log IS NULL OR jsonb_array_length(v_log) = 0 THEN CONTINUE; END IF;
    v_last_idx   := jsonb_array_length(v_log) - 1;
    v_last_entry := v_log -> v_last_idx;
    IF (v_last_entry ->> 'resumed_at') IS NULL THEN
      UPDATE commissions
      SET clock_pause_log = jsonb_set(
        clock_pause_log,
        ARRAY[v_last_idx::text, 'resumed_at'],
        to_jsonb(now()::text)
      )
      WHERE id = v_cid;
    END IF;
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_onboarding_step_rpc(p_center_id uuid, p_step integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_center RECORD;
BEGIN
  IF p_step < 1 OR p_step > 4 THEN
    RAISE EXCEPTION 'invalid_step' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_center
  FROM centers
  WHERE id = p_center_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'center_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Idempotent: if this step already done, return early
  IF (v_center.onboarding_step IS NOT NULL AND v_center.onboarding_step >= p_step) THEN
    RETURN jsonb_build_object(
      'success',          true,
      'already_complete', true,
      'onboarding_step',  v_center.onboarding_step
    );
  END IF;

  UPDATE centers
  SET
    onboarding_step            = p_step,
    onboarding_step_updated_at = NOW(),
    -- Step 3 = Simulate Scan: stamp first_scan_at if not already set
    first_scan_at              = CASE
      WHEN p_step = 3 AND first_scan_at IS NULL THEN NOW()
      ELSE first_scan_at
    END,
    -- Step 4 = ROI Screen: funnel complete
    onboarding_completed_at    = CASE
      WHEN p_step = 4 AND onboarding_completed_at IS NULL THEN NOW()
      ELSE onboarding_completed_at
    END,
    -- Also flip the boolean flag that already exists
    onboarding_completed       = CASE
      WHEN p_step = 4 THEN true
      ELSE onboarding_completed
    END
  WHERE id = p_center_id;

  RETURN jsonb_build_object(
    'success',          true,
    'already_complete', false,
    'onboarding_step',  p_step
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.compute_active_days(p_commission_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_c           commissions%ROWTYPE;
  v_paused_days NUMERIC := 0;
  v_entry       JSONB;
  v_paused_at   TIMESTAMPTZ;
  v_resumed_at  TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_c FROM commissions WHERE id = p_commission_id;
  IF v_c.center_first_payment_date IS NULL THEN RETURN 0; END IF;
  FOR v_entry IN SELECT * FROM jsonb_array_elements(v_c.clock_pause_log)
  LOOP
    v_paused_at  := (v_entry ->> 'paused_at')::TIMESTAMPTZ;
    v_resumed_at := COALESCE((v_entry ->> 'resumed_at')::TIMESTAMPTZ, now());
    v_paused_days := v_paused_days + EXTRACT(EPOCH FROM (v_resumed_at - v_paused_at)) / 86400;
  END LOOP;
  RETURN GREATEST(0, (CURRENT_DATE - v_c.center_first_payment_date) - v_paused_days::INTEGER);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.compute_benchmark_snapshots(p_snapshot_date date DEFAULT CURRENT_DATE)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rows_affected INTEGER := 0;
BEGIN
  -- Per-center metrics for active centers with district and tier
  WITH center_metrics AS (
    SELECT
      c.id,
      c.district,
      COALESCE(c.student_count_tier, 'medium') AS tier,
      -- attendance_rate: unique students scanned last 30d / total active students
      CASE
        WHEN sc.total_students > 0 THEN
          LEAST(1.0, (sc.unique_scanned_30d::NUMERIC / sc.total_students))
        ELSE NULL
      END AS attendance_rate,
      -- revenue_per_student: confirmed payments last 30d / total students
      CASE
        WHEN sc.total_students > 0 AND rev.revenue_30d IS NOT NULL THEN
          rev.revenue_30d / sc.total_students
        ELSE NULL
      END AS revenue_per_student,
      -- retention_rate_30d: students active 30d ago still active / students active 30d ago
      ret.retention_rate AS retention_rate_30d,
      -- group_utilization: students in groups / total students (or 0 if no groups)
      CASE
        WHEN sc.total_students > 0 AND grp.students_in_groups IS NOT NULL THEN
          LEAST(1.0, grp.students_in_groups::NUMERIC / sc.total_students)
        WHEN sc.total_students = 0 THEN 0
        ELSE NULL
      END AS group_utilization
    FROM centers c
    LEFT JOIN LATERAL (
      SELECT
        COUNT(DISTINCT s.id)::INTEGER AS total_students,
        (SELECT COUNT(DISTINCT a.student_id) FROM attendance_scans a
         WHERE a.center_id = c.id AND a.scanned_at >= (p_snapshot_date - interval '30 days'))::INTEGER AS unique_scanned_30d
      FROM students s
      WHERE s.center_id = c.id AND (s.is_active IS NULL OR s.is_active = true)
    ) sc ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(p.amount), 0) AS revenue_30d
      FROM payments p
      WHERE p.center_id = c.id
        AND p.paid_at >= (p_snapshot_date - interval '30 days')
        AND (p.status IN ('confirmed', 'paid') OR p.confirmed = true)
    ) rev ON true
    LEFT JOIN LATERAL (
      SELECT
        CASE
          WHEN active_30d_ago > 0 THEN still_active::NUMERIC / active_30d_ago
          ELSE NULL
        END AS retention_rate
      FROM (
        SELECT
          (SELECT COUNT(DISTINCT student_id) FROM attendance_scans
           WHERE center_id = c.id AND scanned_at >= (p_snapshot_date - interval '37 days')
             AND scanned_at < (p_snapshot_date - interval '30 days'))::INTEGER AS active_30d_ago,
          (SELECT COUNT(DISTINCT a.student_id) FROM attendance_scans a
           WHERE a.center_id = c.id
             AND a.scanned_at >= (p_snapshot_date - interval '7 days')
             AND EXISTS (
               SELECT 1 FROM attendance_scans a2
               WHERE a2.center_id = c.id AND a2.student_id = a.student_id
                 AND a2.scanned_at >= (p_snapshot_date - interval '37 days')
                 AND a2.scanned_at < (p_snapshot_date - interval '30 days')
             ))::INTEGER AS still_active
      ) sub
    ) ret ON true
    LEFT JOIN LATERAL (
      SELECT COUNT(DISTINCT sgm.student_id)::INTEGER AS students_in_groups
      FROM student_group_members sgm
      JOIN student_groups sg ON sg.id = sgm.group_id AND sg.center_id = c.id
    ) grp ON true
    WHERE c.status = 'active'
      AND c.district IS NOT NULL
      AND c.district != ''
  ),
  grouped AS (
    SELECT
      district,
      tier,
      COUNT(*)::INTEGER AS center_count,
      AVG(attendance_rate) AS avg_attendance_rate,
      PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY attendance_rate) AS p25_attendance_rate,
      PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY attendance_rate) AS p50_attendance_rate,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY attendance_rate) AS p75_attendance_rate,
      AVG(revenue_per_student) AS avg_revenue_per_student,
      PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY revenue_per_student) AS p25_revenue,
      PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY revenue_per_student) AS p50_revenue,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY revenue_per_student) AS p75_revenue,
      AVG(retention_rate_30d) AS avg_retention_rate_30d,
      PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY retention_rate_30d) AS p25_retention,
      PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY retention_rate_30d) AS p50_retention,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY retention_rate_30d) AS p75_retention,
      AVG(group_utilization) AS avg_group_utilization,
      PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY group_utilization) AS p25_util,
      PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY group_utilization) AS p50_util,
      PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY group_utilization) AS p75_util
    FROM center_metrics
    WHERE district IS NOT NULL
    GROUP BY district, tier
  )
  INSERT INTO benchmark_snapshots (
    snapshot_date, district, student_count_tier, center_count,
    avg_attendance_rate, p25_attendance_rate, p50_attendance_rate, p75_attendance_rate,
    avg_revenue_per_student, p25_revenue_per_student, p50_revenue_per_student, p75_revenue_per_student,
    avg_retention_rate_30d, p25_retention_rate_30d, p50_retention_rate_30d, p75_retention_rate_30d,
    avg_group_utilization, p25_group_utilization, p50_group_utilization, p75_group_utilization
  )
  SELECT
    p_snapshot_date, district, tier, center_count,
    ROUND(avg_attendance_rate::NUMERIC, 4),
    ROUND(p25_attendance_rate::NUMERIC, 4),
    ROUND(p50_attendance_rate::NUMERIC, 4),
    ROUND(p75_attendance_rate::NUMERIC, 4),
    ROUND(avg_revenue_per_student::NUMERIC, 2),
    ROUND(p25_revenue::NUMERIC, 2),
    ROUND(p50_revenue::NUMERIC, 2),
    ROUND(p75_revenue::NUMERIC, 2),
    ROUND(avg_retention_rate_30d::NUMERIC, 4),
    ROUND(p25_retention::NUMERIC, 4),
    ROUND(p50_retention::NUMERIC, 4),
    ROUND(p75_retention::NUMERIC, 4),
    ROUND(avg_group_utilization::NUMERIC, 4),
    ROUND(p25_util::NUMERIC, 4),
    ROUND(p50_util::NUMERIC, 4),
    ROUND(p75_util::NUMERIC, 4)
  FROM grouped
  ON CONFLICT (snapshot_date, district, student_count_tier)
  DO UPDATE SET
    center_count = EXCLUDED.center_count,
    avg_attendance_rate = EXCLUDED.avg_attendance_rate,
    p25_attendance_rate = EXCLUDED.p25_attendance_rate,
    p50_attendance_rate = EXCLUDED.p50_attendance_rate,
    p75_attendance_rate = EXCLUDED.p75_attendance_rate,
    avg_revenue_per_student = EXCLUDED.avg_revenue_per_student,
    p25_revenue_per_student = EXCLUDED.p25_revenue_per_student,
    p50_revenue_per_student = EXCLUDED.p50_revenue_per_student,
    p75_revenue_per_student = EXCLUDED.p75_revenue_per_student,
    avg_retention_rate_30d = EXCLUDED.avg_retention_rate_30d,
    p25_retention_rate_30d = EXCLUDED.p25_retention_rate_30d,
    p50_retention_rate_30d = EXCLUDED.p50_retention_rate_30d,
    p75_retention_rate_30d = EXCLUDED.p75_retention_rate_30d,
    avg_group_utilization = EXCLUDED.avg_group_utilization,
    p25_group_utilization = EXCLUDED.p25_group_utilization,
    p50_group_utilization = EXCLUDED.p50_group_utilization,
    p75_group_utilization = EXCLUDED.p75_group_utilization;

  GET DIAGNOSTICS rows_affected = ROW_COUNT;
  RETURN rows_affected;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.compute_center_health_score(p_center_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  score INTEGER := 50;
  scans_7d INT;
  onboarding_done BOOLEAN;
  payment_ok BOOLEAN;
  parent_comms BOOLEAN;
  daily_summary BOOLEAN;
  referral_sent BOOLEAN;
BEGIN
  SELECT COUNT(*)::INT INTO scans_7d
  FROM attendance_scans
  WHERE center_id = p_center_id
    AND scanned_at >= (now() - interval '7 days');
  IF scans_7d = 0 THEN score := score - 30; END IF;

  SELECT COALESCE(c.onboarding_completed, false) INTO onboarding_done
  FROM centers c WHERE c.id = p_center_id;
  IF onboarding_done THEN score := score + 20; END IF;

  SELECT
    COALESCE(c.subscription_status, 'active') = 'active'
    AND NOT EXISTS (
      SELECT 1 FROM invoices i
      WHERE i.center_id = p_center_id
        AND i.status NOT IN ('paid', 'cancelled')
        AND i.due_date < CURRENT_DATE
    )
  INTO payment_ok
  FROM centers c WHERE c.id = p_center_id;
  IF payment_ok THEN score := score + 25; END IF;

  SELECT
    COALESCE(c.individual_alerts_enabled, false)
    OR EXISTS (SELECT 1 FROM students s WHERE s.center_id = p_center_id AND s.parent_phone IS NOT NULL AND s.parent_phone != '')
  INTO parent_comms
  FROM centers c WHERE c.id = p_center_id;
  IF parent_comms THEN score := score + 10; END IF;

  SELECT COALESCE(c.daily_summary_enabled, true) INTO daily_summary
  FROM centers c WHERE c.id = p_center_id;
  IF daily_summary THEN score := score + 5; END IF;

  SELECT
    c.referred_by IS NOT NULL
    OR EXISTS (SELECT 1 FROM referrals r WHERE r.referrer_center_id = p_center_id)
  INTO referral_sent
  FROM centers c WHERE c.id = p_center_id;
  IF referral_sent THEN score := score + 10; END IF;

  score := LEAST(100, GREATEST(0, score));
  RETURN score;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.compute_lesson_money(p_lesson_fee numeric, p_method text)
 RETURNS TABLE(lesson_fee numeric, customer_commission_amt numeric, processing_fee_amt numeric, amount_billed numeric, teacher_commission_amt numeric, teacher_net numeric, platform_gross numeric, platform_net numeric, snap_vat_amount numeric, snap_customer_pct numeric, snap_teacher_pct numeric, snap_processing_flat numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cfg jsonb;
  v_cp  numeric;
  v_tp  numeric;
  v_pf  numeric;
  v_vat numeric;
  v_fee numeric := round(coalesce(p_lesson_fee, 0), 2);
begin
  if v_fee < 0 then
    raise exception 'lesson_fee cannot be negative (got %)', v_fee using errcode = '22023';
  end if;

  -- Cash and instapay never touch Paymob, so they carry no cut.
  if p_method not in ('card','wallet','apple_pay','google_pay') then
    lesson_fee := v_fee; customer_commission_amt := 0; processing_fee_amt := 0;
    amount_billed := v_fee; teacher_commission_amt := 0; teacher_net := v_fee;
    platform_gross := 0; platform_net := 0; snap_vat_amount := 0;
    snap_customer_pct := 0; snap_teacher_pct := 0; snap_processing_flat := 0;
    return next; return;
  end if;

  -- Rates live in one config row. Anything missing reads as 0.
  select value into v_cfg from public.platform_config where key = 'lesson_commission';
  v_cp  := coalesce((v_cfg->>'customer_pct')::numeric, 0);
  v_tp  := coalesce((v_cfg->>'teacher_pct')::numeric, 0);
  v_pf  := coalesce((v_cfg->>'processing_flat')::numeric, 0);
  v_vat := coalesce((v_cfg->>'vat_pct')::numeric, 0);

  if v_cp < 0 or v_cp >= 1 then
    raise exception 'customer_pct must be in [0,1) (got %)', v_cp using errcode = '22023';
  end if;
  if v_tp < 0 or v_tp > 1 then
    raise exception 'teacher_pct must be in [0,1] (got %)', v_tp using errcode = '22023';
  end if;
  if v_pf < 0 then
    raise exception 'processing_flat must be >= 0 (got %)', v_pf using errcode = '22023';
  end if;
  if v_vat < 0 then
    raise exception 'vat_pct must be >= 0 (got %)', v_vat using errcode = '22023';
  end if;

  snap_customer_pct    := v_cp;
  snap_teacher_pct     := v_tp;
  snap_processing_flat := v_pf;

  lesson_fee         := v_fee;
  processing_fee_amt := round(v_pf, 2);

  -- Customer cut is taken out of the billed total, grossed up so tuition + processing stay whole:
  --   amount_billed = (tuition + processing) / (1 - customer_pct)
  amount_billed           := round((v_fee + processing_fee_amt) / (1 - v_cp), 2);
  -- Derive the cut as the remainder so lesson_fee + customer_commission + processing = amount_billed exactly.
  customer_commission_amt := amount_billed - v_fee - processing_fee_amt;

  -- Teacher cut is a straight deduction from tuition.
  teacher_commission_amt := round(v_fee * v_tp, 2);
  teacher_net            := v_fee - teacher_commission_amt;

  -- Your money is both cuts. Processing is pass-through to Paymob, not yours.
  platform_gross  := customer_commission_amt + teacher_commission_amt;
  -- VAT carved out of your cut (VAT-inclusive): gross * vat / (1 + vat).
  snap_vat_amount := round(platform_gross * v_vat / (1 + v_vat), 2);
  platform_net    := platform_gross - snap_vat_amount;

  return next;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.compute_student_count_tier()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  cid UUID;
  cnt INTEGER;
  tier TEXT;
BEGIN
  cid := COALESCE(NEW.center_id, OLD.center_id);
  IF cid IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT COUNT(*)::INTEGER INTO cnt
  FROM students
  WHERE center_id = cid
    AND (is_active IS NULL OR is_active = true);
  IF cnt < 150 THEN tier := 'small';
  ELSIF cnt <= 500 THEN tier := 'medium';
  ELSE tier := 'large';
  END IF;
  UPDATE centers SET student_count_tier = tier WHERE id = cid;
  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.confirm_group_slot(p_slot_proposal_id uuid, p_center_id uuid, p_actor_user_id uuid, p_room_id uuid DEFAULT NULL::uuid)
 RETURNS schedule_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_p     public.group_slot_proposals%rowtype;
  v_group public.student_groups%rowtype;
  v_room  uuid;
  v_dow   text;
  v_slot  public.schedule_slots%rowtype;
begin
  select * into v_p from public.group_slot_proposals where id = p_slot_proposal_id for update;
  if not found then
    raise exception 'slot proposal % not found', p_slot_proposal_id using errcode = 'P0002';
  end if;
  if v_p.status <> 'pending' then
    raise exception 'slot proposal is not pending (status %)', v_p.status using errcode = '23514';
  end if;

  select * into v_group from public.student_groups where id = v_p.group_id for update;
  if not found then
    raise exception 'group not found' using errcode = 'P0002';
  end if;
  if v_group.center_id is distinct from p_center_id then
    raise exception 'slot proposal % not found', p_slot_proposal_id using errcode = 'P0002';
  end if;
  if v_group.kind <> 'center' then
    raise exception 'group is no longer center-attached' using errcode = '23514';
  end if;

  v_room := coalesce(p_room_id, v_p.room_id);
  if v_room is not null then
    perform 1 from public.rooms where id = v_room and center_id = p_center_id;
    if not found then
      raise exception 'room % not in this center', v_room using errcode = '23514';
    end if;
  end if;
  v_dow := v_p.day_of_week::text;

  if v_room is not null then
    perform 1 from public.schedule_slots s
      where s.center_id = p_center_id
        and s.room_id = v_room
        and s.day_of_week = v_dow
        and s.start_time < v_p.end_time
        and s.end_time   > v_p.start_time;
    if found then
      raise exception 'room is already booked at this time' using errcode = '23P01';
    end if;
  end if;
  if v_group.teacher_id is not null then
    perform 1 from public.schedule_slots s
      where s.teacher_id = v_group.teacher_id
        and s.day_of_week = v_dow
        and s.start_time < v_p.end_time
        and s.end_time   > v_p.start_time;
    if found then
      raise exception 'teacher is already booked at this time' using errcode = '23P01';
    end if;
  end if;

  insert into public.schedule_slots
    (center_id, room_id, group_id, teacher_id, subject, day_of_week, start_time, end_time, recurring)
  values
    (p_center_id, v_room, v_group.id, v_group.teacher_id, v_group.subject, v_dow,
     v_p.start_time, v_p.end_time, true)
  returning * into v_slot;

  update public.group_slot_proposals
     set status = 'confirmed',
         created_slot_id = v_slot.id,
         responded_by = p_actor_user_id,
         responded_at = now(),
         room_id = v_room,
         updated_at = now()
   where id = p_slot_proposal_id;

  return v_slot;
end $function$
;
CREATE OR REPLACE FUNCTION public.create_enrollment(p_group_id uuid, p_student_id uuid, p_payer text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text)
 RETURNS TABLE(enrollment_id uuid, status text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_group       public.student_groups%rowtype;
  v_teacher_id  uuid;
  v_live_count  int;
  v_status      text;
  v_new_id      uuid;
begin
  select * into v_group from public.student_groups sg where sg.id = p_group_id for update;
  if not found then
    raise exception 'group % not found', p_group_id using errcode = 'P0002';
  end if;
  if v_group.status <> 'active' then
    raise exception 'group % is not active (status %)', p_group_id, v_group.status using errcode = '23514';
  end if;

  if p_payer is not null and p_payer not in ('student','parent') then
    raise exception 'invalid payer %', p_payer using errcode = '23514';
  end if;
  if p_source is not null and p_source not in ('self_link','walk_in','inherited','import') then
    raise exception 'invalid source %', p_source using errcode = '23514';
  end if;

  v_teacher_id := v_group.teacher_id;
  if v_teacher_id is not null
     and exists (select 1 from public.teacher_subscriptions ts
                 where ts.teacher_id = v_teacher_id and ts.status = 'suspended') then
    raise exception 'teacher % is suspended; enrollment blocked', v_teacher_id using errcode = '23514';
  end if;

  if not exists (select 1 from public.students st where st.id = p_student_id) then
    raise exception 'student % not found', p_student_id using errcode = 'P0002';
  end if;

  if exists (select 1 from public.enrollments e
             where e.group_id = p_group_id and e.student_id = p_student_id
               and e.status in ('pending','active')) then
    raise exception 'student % already has a live enrollment in group %', p_student_id, p_group_id
      using errcode = '23505';
  end if;

  if v_group.capacity_cap is not null then
    select count(*) into v_live_count
    from public.enrollments e
    where e.group_id = p_group_id and e.status in ('pending','active');
    if v_live_count >= v_group.capacity_cap then
      raise exception 'group % is at capacity (% / %)', p_group_id, v_live_count, v_group.capacity_cap
        using errcode = '23514';
    end if;
  end if;

  if coalesce(v_group.approval_mode, 'manual') = 'auto_cap' then
    v_status := 'active';
  else
    v_status := 'pending';
  end if;

  insert into public.enrollments (group_id, student_id, status, payer, source, approved_by, joined_at)
  values (
    p_group_id, p_student_id, v_status, p_payer, p_source,
    case when v_status = 'active' then p_actor_id else null end,
    case when v_status = 'active' then now() else null end
  )
  returning id into v_new_id;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values (
    'enrollment_created', 'enrollment', v_new_id, p_actor_id, v_group.center_id,
    jsonb_build_object('group_id', p_group_id, 'student_id', p_student_id, 'status', v_status, 'source', p_source)
  );

  return query select v_new_id, v_status;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.create_referral_reward()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  fee NUMERIC;
BEGIN
  IF NEW.referred_by IS NULL OR COALESCE(NEW.subscription_status, 'active') != 'active' THEN
    RETURN NEW;
  END IF;
  SELECT monthly_fee INTO fee FROM pricing_plans WHERE id = COALESCE(NEW.plan, 'starter');
  IF fee IS NULL OR fee <= 0 THEN
    fee := CASE COALESCE(NEW.plan, 'starter')
      WHEN 'starter' THEN 4000
      WHEN 'pro' THEN 7200
      WHEN 'pro_plus' THEN 8000
      WHEN 'enterprise' THEN 9000
      ELSE 4000
    END;
  END IF;
  INSERT INTO referral_rewards (referring_center_id, referred_center_id, referred_center_plan, first_month_fee, reward_amount, reward_status)
  VALUES (NEW.referred_by, NEW.id, COALESCE(NEW.plan, 'starter'), fee, fee * 0.20, 'approved')
  ON CONFLICT (referring_center_id, referred_center_id) DO UPDATE SET reward_status = 'approved', reward_amount = EXCLUDED.reward_amount;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.decline_group_slot(p_slot_proposal_id uuid, p_center_id uuid, p_actor_user_id uuid)
 RETURNS group_slot_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_p     public.group_slot_proposals%rowtype;
  v_group public.student_groups%rowtype;
  v_row   public.group_slot_proposals%rowtype;
begin
  select * into v_p from public.group_slot_proposals where id = p_slot_proposal_id for update;
  if not found then
    raise exception 'slot proposal % not found', p_slot_proposal_id using errcode = 'P0002';
  end if;
  if v_p.status <> 'pending' then
    raise exception 'slot proposal is not pending (status %)', v_p.status using errcode = '23514';
  end if;

  select * into v_group from public.student_groups where id = v_p.group_id;
  if not found or v_group.center_id is distinct from p_center_id then
    raise exception 'slot proposal % not found', p_slot_proposal_id using errcode = 'P0002';
  end if;

  update public.group_slot_proposals
     set status = 'declined', responded_by = p_actor_user_id, responded_at = now(), updated_at = now()
   where id = p_slot_proposal_id
  returning * into v_row;

  return v_row;
end $function$
;
CREATE OR REPLACE FUNCTION public.deduct_blast_balance_rpc(p_center_id uuid, p_blast_type text, p_parent_count integer, p_message_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cap           INTEGER;
  v_current_month TEXT;
  v_current_count INTEGER;
  v_blast_id      UUID;
  v_cap_config    JSONB;
BEGIN
  v_current_month := to_char(NOW(), 'YYYY-MM');

  -- Fetch cap from platform_config (key-value pattern)
  SELECT value INTO v_cap_config
  FROM platform_config
  WHERE key = 'announcement_cap_monthly';

  v_cap := COALESCE((v_cap_config)::INTEGER, 2);

  -- Count blasts this month for this center
  SELECT COUNT(*) INTO v_current_count
  FROM announcement_blasts
  WHERE center_id = p_center_id
    AND to_char(created_at, 'YYYY-MM') = v_current_month;

  IF v_current_count >= v_cap THEN
    RETURN jsonb_build_object(
      'success',       false,
      'error',         'cap_exceeded',
      'current_count', v_current_count,
      'cap',           v_cap
    );
  END IF;

  -- Insert announcement blast record
  INSERT INTO announcement_blasts (
    center_id,
    sent_by,
    template_name,
    blast_type,
    message,
    parents_notified,
    base_amount,
    service_fee,
    vat,
    total_amount,
    billing_status
  )
  VALUES (
    p_center_id,
    NULL,
    CASE
      WHEN p_blast_type = 'promo' THEN 'chq_parent_announcement_promo'
      ELSE 'chq_parent_announcement_ops'
    END,
    p_blast_type,
    p_message_body,
    p_parent_count,
    -- base: 8 EGP * parent_count
    ROUND((8 * p_parent_count)::NUMERIC, 2),
    -- service fee 6.5% of base
    ROUND((8 * p_parent_count * 0.065)::NUMERIC, 2),
    -- VAT 14% of base
    ROUND((8 * p_parent_count * 0.14)::NUMERIC, 2),
    -- total inclusive: 9.71 * parent_count
    ROUND((9.71 * p_parent_count)::NUMERIC, 2),
    'pending'
  )
  RETURNING id INTO v_blast_id;

  RETURN jsonb_build_object(
    'success',     true,
    'blast_id',    v_blast_id,
    'new_count',   v_current_count + 1,
    'cap',         v_cap,
    'total_amount', ROUND((9.71 * p_parent_count)::NUMERIC, 2)
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.deduct_blast_credits(p_user_id uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub         numeric;
  v_purch       numeric;
  v_sub_deduct  numeric;
  v_purch_deduct numeric;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'p_amount must be positive' using errcode = '22023';
  end if;

  select blast_credits_subscription, blast_credits_purchased
    into v_sub, v_purch
    from public.teacher_profiles
   where user_id = p_user_id
   for update;
  if not found then
    raise exception 'no teacher profile for %', p_user_id using errcode = 'P0002';
  end if;

  if (v_sub + v_purch) < p_amount then
    raise exception 'INSUFFICIENT_CREDITS' using errcode = '23514';
  end if;

  v_sub_deduct   := least(v_sub, p_amount);
  v_purch_deduct := p_amount - v_sub_deduct;

  update public.teacher_profiles
     set blast_credits_subscription = v_sub - v_sub_deduct,
         blast_credits_purchased    = v_purch - v_purch_deduct
   where user_id = p_user_id;

  return jsonb_build_object(
    'subscription_used',      v_sub_deduct,
    'purchased_used',         v_purch_deduct,
    'subscription_remaining', v_sub - v_sub_deduct,
    'purchased_remaining',    v_purch - v_purch_deduct
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.detach_center_from_group(p_group_id uuid, p_actor_user_id uuid)
 RETURNS TABLE(group_id uuid, group_kind text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group public.student_groups%rowtype;
begin
  select * into v_group from public.student_groups where id = p_group_id for update;
  if not found then
    raise exception 'group % not found', p_group_id using errcode = 'P0002';
  end if;
  if v_group.teacher_id is distinct from p_actor_user_id then
    raise exception 'group % not found', p_group_id using errcode = 'P0002';
  end if;
  if v_group.kind <> 'center' or v_group.center_id is null then
    raise exception 'group % is not center-attached', p_group_id using errcode = '23514';
  end if;

  update public.student_groups
     set kind = 'private',
         center_id = null,
         center_cut_egp = 0,
         approval_mode = coalesce(approval_mode, 'manual')
   where id = p_group_id;

  return query select p_group_id, 'private'::text;
end $function$
;
CREATE OR REPLACE FUNCTION public.downgrade_teacher_to_standard(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sub public.teacher_subscriptions;
begin
  select * into v_sub from public.teacher_subscriptions where teacher_id=p_user_id for update;
  if not found then raise exception 'no teacher subscription for %', p_user_id using errcode='P0002'; end if;
  if v_sub.plan_key='teacher_standard' then return jsonb_build_object('already_standard', true); end if;
  if v_sub.plan_key not in ('teacher_pro','teacher_scale') then
    raise exception 'unexpected plan_key % on downgrade', v_sub.plan_key using errcode='23514';
  end if;
  update public.teacher_subscriptions
     set plan_key='teacher_standard', price_gross=499, price_net=437.72, snap_vat_amount=61.28
   where id=v_sub.id;
  update public.teacher_profiles set plan_key='teacher_standard', blast_credits_subscription=0 where user_id=p_user_id;
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('teacher_downgraded_to_standard','teacher_subscription',v_sub.id,p_user_id,null,
          jsonb_build_object('from_plan',v_sub.plan_key,'to_plan','teacher_standard'));
  return jsonb_build_object('downgraded', true);
end; $function$
;
CREATE OR REPLACE FUNCTION public.earn_credits_atomic(p_center_id uuid, p_amount numeric, p_reference_id uuid, p_reference_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_balance NUMERIC;
  v_current_plan TEXT;
  v_all_in_price NUMERIC;
  v_max_balance NUMERIC;
  v_new_balance NUMERIC;
  v_expires_at TIMESTAMPTZ;
BEGIN
  SELECT credit_balance, plan, all_in_price
  INTO v_current_balance, v_current_plan, v_all_in_price
  FROM centers WHERE id = p_center_id FOR UPDATE;

  v_max_balance := COALESCE(v_all_in_price, 0) * 3;
  v_expires_at := NOW() + INTERVAL '6 months';

  INSERT INTO credit_ledger (
    center_id, amount, type,
    reference_id, reference_type, expires_at
  ) VALUES (
    p_center_id, p_amount, 'earned',
    p_reference_id, p_reference_type, v_expires_at
  );

  v_new_balance := LEAST(v_max_balance, v_current_balance + p_amount);

  UPDATE centers
  SET credit_balance = v_new_balance
  WHERE id = p_center_id;

  RETURN v_new_balance;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_payout_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'paid' THEN
    RAISE EXCEPTION 'Cannot modify a paid payout — use adjustment_amount on next payout';
  END IF;
  IF OLD.status = 'confirmed' AND NEW.status = 'draft' THEN
    RAISE EXCEPTION 'Cannot revert a confirmed payout to draft';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.finish_center_class_and_bill(p_session_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(session_id uuid, billed_now boolean, charges_created integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session    public.sessions%rowtype;
  v_group      public.student_groups%rowtype;
  v_fee        numeric;
  v_cut        numeric;
  v_teacher_id uuid;
  v_center_id  uuid;
  v_count      int := 0;
  v_attendee   record;
  v_payer      text;
  v_payer_phone text;
  v_lesson_key text;
  v_center_key text;
BEGIN
  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'session % not found', p_session_id USING errcode = 'P0002';
  END IF;

  IF v_session.billed THEN
    RETURN QUERY SELECT v_session.id, false, 0;
    RETURN;
  END IF;

  IF v_session.status = 'cancelled' THEN
    RAISE EXCEPTION 'cannot bill a cancelled session %', p_session_id USING errcode = '23514';
  END IF;

  IF v_session.kind <> 'center' THEN
    RAISE EXCEPTION 'finish_center_class_and_bill is center-only; session % is kind %',
      p_session_id, v_session.kind USING errcode = '23514';
  END IF;

  SELECT * INTO v_group FROM public.student_groups
    WHERE id = v_session.group_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'group % for session % not found',
      v_session.group_id, p_session_id USING errcode = 'P0002';
  END IF;

  v_fee        := v_group.fee_per_class;
  v_cut        := COALESCE(v_group.center_cut_egp, 0);
  v_teacher_id := v_group.teacher_id;
  v_center_id  := v_group.center_id;

  IF v_fee IS NULL THEN
    RAISE EXCEPTION 'group % has no fee_per_class; cannot bill', v_group.id
      USING errcode = '23514';
  END IF;
  IF v_teacher_id IS NULL THEN
    RAISE EXCEPTION 'group % has no teacher_id; cannot bill', v_group.id
      USING errcode = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.teacher_profiles tp WHERE tp.user_id = v_teacher_id
  ) THEN
    RAISE EXCEPTION 'no teacher_profile for user %; cannot bill group %',
      v_teacher_id, v_group.id USING errcode = '23503';
  END IF;

  IF v_session.status <> 'finished' THEN
    PERFORM public.apply_session_transition(p_session_id, 'finished', p_actor_id);
  END IF;

  FOR v_attendee IN
    SELECT a.student_id FROM public.attendance_scans a
    WHERE a.session_id = p_session_id AND a.billable = true
  LOOP
    v_payer := NULL; v_payer_phone := NULL;

    SELECT e.payer INTO v_payer FROM public.enrollments e
      WHERE e.group_id = v_session.group_id AND e.student_id = v_attendee.student_id;

    IF v_payer = 'parent' THEN
      SELECT s.parent_phone INTO v_payer_phone FROM public.students s
        WHERE s.id = v_attendee.student_id;
    ELSIF v_payer = 'student' THEN
      SELECT s.phone INTO v_payer_phone FROM public.students s
        WHERE s.id = v_attendee.student_id;
    END IF;

    v_lesson_key := 'lesson:' || p_session_id::text || ':' || v_attendee.student_id::text;
    v_center_key := 'center_fee:' || p_session_id::text || ':' || v_attendee.student_id::text;

    INSERT INTO public.transactions (
      kind, session_id, enrollment_id, student_id, group_id,
      teacher_id, center_id, lesson_fee, amount_billed,
      payer_type, payer_phone, status, idempotency_key, created_by
    )
    SELECT 'lesson', p_session_id,
      (SELECT e.id FROM public.enrollments e
        WHERE e.group_id = v_session.group_id AND e.student_id = v_attendee.student_id),
      v_attendee.student_id, v_session.group_id,
      v_teacher_id, v_center_id, v_fee, v_fee,
      v_payer, v_payer_phone, 'pending', v_lesson_key, p_actor_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.transactions t WHERE t.idempotency_key = v_lesson_key
    );
    IF FOUND THEN v_count := v_count + 1; END IF;

    IF v_cut > 0 THEN
      INSERT INTO public.transactions (
        kind, session_id, enrollment_id, student_id, group_id,
        teacher_id, center_id, lesson_fee, amount_billed,
        status, idempotency_key, created_by
      )
      SELECT 'center_fee', p_session_id,
        (SELECT e.id FROM public.enrollments e
          WHERE e.group_id = v_session.group_id AND e.student_id = v_attendee.student_id),
        v_attendee.student_id, v_session.group_id,
        v_teacher_id, v_center_id, v_cut, v_cut,
        'pending', v_center_key, p_actor_id
      WHERE NOT EXISTS (
        SELECT 1 FROM public.transactions t WHERE t.idempotency_key = v_center_key
      );
    END IF;

  END LOOP;

  SET LOCAL app.allow_lifecycle_write = 'on';
  UPDATE public.sessions SET billed = true, billed_at = now() WHERE id = p_session_id;
  SET LOCAL app.allow_lifecycle_write = 'off';

  INSERT INTO public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  VALUES (
    'center_class_finished_billed', 'session', p_session_id, p_actor_id, v_center_id,
    jsonb_build_object(
      'charges_created', v_count,
      'fee_per_class', v_fee,
      'center_cut_egp', v_cut,
      'teacher_id', v_teacher_id
    )
  );

  RETURN QUERY SELECT p_session_id, true, v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.finish_class_and_bill(p_session_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(session_id uuid, billed_now boolean, charges_created integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_session public.sessions%rowtype; v_group public.student_groups%rowtype;
  v_fee numeric; v_teacher_id uuid; v_center_id uuid; v_count int:=0;
  v_attendee record; v_payer text; v_payer_phone text;
begin
  select * into v_session from public.sessions where id=p_session_id for update;
  if not found then raise exception 'session % not found', p_session_id using errcode='P0002'; end if;
  if v_session.billed then return query select v_session.id,false,0; return; end if;
  if v_session.status='cancelled' then raise exception 'cannot bill a cancelled session %', p_session_id using errcode='23514'; end if;
  if v_session.kind<>'private' then raise exception 'finish_class_and_bill is private-only; session % is kind %', p_session_id, v_session.kind using errcode='23514'; end if;
  select * into v_group from public.student_groups where id=v_session.group_id for update;
  if not found then raise exception 'group % for session % not found', v_session.group_id, p_session_id using errcode='P0002'; end if;
  v_fee:=v_group.fee_per_class; v_teacher_id:=v_group.teacher_id; v_center_id:=v_group.center_id;
  if v_fee is null then raise exception 'group % has no fee_per_class; cannot bill', v_group.id using errcode='23514'; end if;
  if v_teacher_id is null then raise exception 'group % has no teacher_id; cannot bill', v_group.id using errcode='23514'; end if;
  if not exists (select 1 from public.teacher_profiles tp where tp.user_id=v_teacher_id) then
    raise exception 'no teacher_profile for user %; cannot bill group %', v_teacher_id, v_group.id using errcode='23503'; end if;
  if v_session.status<>'finished' then perform public.apply_session_transition(p_session_id,'finished',p_actor_id); end if;
  for v_attendee in select a.student_id from public.attendance_scans a where a.session_id=p_session_id and a.billable=true
  loop
    v_payer:=null; v_payer_phone:=null;
    select e.payer into v_payer from public.enrollments e where e.group_id=v_session.group_id and e.student_id=v_attendee.student_id;
    if v_payer='parent' then select s.parent_phone into v_payer_phone from public.students s where s.id=v_attendee.student_id;
    elsif v_payer='student' then select s.phone into v_payer_phone from public.students s where s.id=v_attendee.student_id; end if;
    insert into public.transactions (kind,session_id,enrollment_id,student_id,group_id,teacher_id,center_id,
      lesson_fee,amount_billed,payer_type,payer_phone,status,idempotency_key,created_by)
    select 'lesson',p_session_id,
      (select e.id from public.enrollments e where e.group_id=v_session.group_id and e.student_id=v_attendee.student_id),
      v_attendee.student_id,v_session.group_id,v_teacher_id,v_center_id,v_fee,v_fee,v_payer,v_payer_phone,'pending',
      'lesson:'||p_session_id::text||':'||v_attendee.student_id::text,p_actor_id
    where not exists (select 1 from public.transactions t where t.idempotency_key='lesson:'||p_session_id::text||':'||v_attendee.student_id::text);
    if found then v_count:=v_count+1; end if;
  end loop;
  set local app.allow_lifecycle_write='on';
  update public.sessions set billed=true, billed_at=now() where id=p_session_id;
  set local app.allow_lifecycle_write='off';
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('class_finished_billed','session',p_session_id,p_actor_id,v_center_id,
          jsonb_build_object('charges_created',v_count,'fee_per_class',v_fee,'teacher_id',v_teacher_id));
  return query select p_session_id,true,v_count;
end; $function$
;
CREATE OR REPLACE FUNCTION public.generate_invoice_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  month_prefix TEXT;
  next_num INT;
  ref_ts TIMESTAMPTZ;
BEGIN
  ref_ts := COALESCE(NEW.created_at, NOW());
  month_prefix := 'INV-' || TO_CHAR(timezone('Africa/Cairo', ref_ts), 'YYYY-MM');
  SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(month_prefix) + 2) AS INT)), 0) + 1
  INTO next_num
  FROM invoices
  WHERE invoice_number LIKE month_prefix || '-%';
  NEW.invoice_number := month_prefix || '-' || LPAD(next_num::TEXT, 3, '0');
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.generate_referral_code_8char()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  result TEXT := '';
  i INT;
BEGIN
  IF NEW.referral_code IS NULL OR LENGTH(TRIM(NEW.referral_code)) != 8 THEN
    FOR i IN 1..8 LOOP
      result := result || substr(chars, 1 + floor(random() * length(chars))::int, 1);
    END LOOP;
    NEW.referral_code := result;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.generate_referral_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.referral_code IS NULL THEN
    NEW.referral_code := UPPER(SUBSTRING(MD5(NEW.id::text || NOW()::text) FROM 1 FOR 8));
  END IF;
  RETURN NEW;
END;
$function$
;
