CREATE OR REPLACE FUNCTION public.invite_teacher_to_center(p_teacher_user_id uuid, p_center_id uuid, p_invited_by uuid DEFAULT NULL::uuid)
 RETURNS teacher_center
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tc public.teacher_center;
begin
  if not exists (select 1 from public.users u where u.id = p_teacher_user_id) then
    raise exception 'user % not found', p_teacher_user_id using errcode='P0002';
  end if;
  if not exists (select 1 from public.centers c where c.id = p_center_id) then
    raise exception 'center % not found', p_center_id using errcode='P0002';
  end if;

  -- Ensure a teacher_profiles row (the teacher identity). Idempotent.
  insert into public.teacher_profiles (user_id)
  values (p_teacher_user_id)
  on conflict (user_id) do nothing;

  -- Create or reactivate the relationship as pending.
  select * into v_tc from public.teacher_center
   where teacher_id = p_teacher_user_id and center_id = p_center_id;

  if found then
    if v_tc.status = 'active' then
      return v_tc;  -- already active, nothing to do
    end if;
    update public.teacher_center
      set status='pending', invited_by=p_invited_by, invited_at=now(), accepted_at=null
      where id=v_tc.id
      returning * into v_tc;
  else
    insert into public.teacher_center (teacher_id, center_id, status, invited_by, invited_at)
    values (p_teacher_user_id, p_center_id, 'pending', p_invited_by, now())
    returning * into v_tc;
  end if;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values ('teacher_invited','teacher_center', v_tc.id, p_invited_by, p_center_id,
          jsonb_build_object('teacher_id', p_teacher_user_id));
  return v_tc;
end; $function$
;
