CREATE OR REPLACE FUNCTION public.issue_student_credit(p_student_id uuid, p_teacher_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_source_transaction_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'credit amount must be > 0, got %', p_amount using errcode = '23514';
  end if;
  if not exists (select 1 from public.students st where st.id = p_student_id) then
    raise exception 'student % not found', p_student_id using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.teacher_profiles tp where tp.user_id = p_teacher_id) then
    raise exception 'teacher % not found', p_teacher_id using errcode = 'P0002';
  end if;
  if p_source_transaction_id is not null
     and not exists (select 1 from public.transactions t where t.id = p_source_transaction_id) then
    raise exception 'source transaction % not found', p_source_transaction_id using errcode = 'P0002';
  end if;

  insert into public.student_credits
    (student_id, teacher_id, amount, reason, source_transaction_id, status, created_by)
  values
    (p_student_id, p_teacher_id, round(p_amount, 2), p_reason, p_source_transaction_id, 'active', p_actor_id)
  returning id into v_id;

  insert into public.audit_log (action, entity_type, entity_id, user_id, details)
  values (
    'credit_issued', 'student_credit', v_id, p_actor_id,
    jsonb_build_object('student_id', p_student_id, 'teacher_id', p_teacher_id,
                       'amount', round(p_amount,2), 'reason', p_reason,
                       'source_transaction_id', p_source_transaction_id)
  );

  return v_id;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.log_card_order_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.card_order_status_transitions (
      card_order_id, from_status, to_status, transitioned_at, metadata
    ) VALUES (
      NEW.id, OLD.status, NEW.status, now(), '{}'::jsonb
    );
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.payments_auto_confirm_cash()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF LOWER(COALESCE(NEW.method, '')) IN ('cash', 'نقدي', 'كاش') THEN
    NEW.confirmed := true;
    NEW.confirmed_at := COALESCE(NEW.confirmed_at, NOW());
    NEW.status := COALESCE(NEW.status, 'confirmed');
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.process_due_subscriptions(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(action_taken text, subscription_id uuid)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_grace_days int;
  v_max_attempts int;
  v_rec record;
begin
  select (value #>> '{}')::int into v_grace_days from public.platform_config where key='subscription_grace_period_days';
  v_grace_days := coalesce(v_grace_days, 7);
  select (value #>> '{}')::int into v_max_attempts from public.platform_config where key='subscription_dunning_max_attempts';
  v_max_attempts := coalesce(v_max_attempts, 3);

  for v_rec in
    select * from public.teacher_subscriptions
    where status in ('trialing','active','past_due')
    for update
  loop
    -- trialing past trial end -> past_due (trial-then-prompt: access pauses)
    if v_rec.status = 'trialing' and v_rec.trial_ends_at is not null and v_rec.trial_ends_at <= p_as_of then
      perform public.apply_teacher_subscription_transition(v_rec.id, 'past_due', null);
      update public.teacher_subscriptions
        set next_billing_at = p_as_of, grace_until = p_as_of + make_interval(days => v_grace_days)
        where id = v_rec.id;
      action_taken := 'trial_expired_to_past_due'; subscription_id := v_rec.id; return next;

    -- active past period end -> past_due (payment now owed)
    elsif v_rec.status = 'active' and v_rec.current_period_end is not null and v_rec.current_period_end <= p_as_of then
      perform public.apply_teacher_subscription_transition(v_rec.id, 'past_due', null);
      update public.teacher_subscriptions
        set grace_until = p_as_of + make_interval(days => v_grace_days)
        where id = v_rec.id;
      action_taken := 'period_ended_to_past_due'; subscription_id := v_rec.id; return next;

    -- past_due -> walk dunning, suspend after max attempts AND grace passed
    elsif v_rec.status = 'past_due' then
      update public.teacher_subscriptions
        set dunning_attempts = dunning_attempts + 1
        where id = v_rec.id;
      if (v_rec.dunning_attempts + 1) >= v_max_attempts
         and v_rec.grace_until is not null and v_rec.grace_until <= p_as_of then
        perform public.apply_teacher_subscription_transition(v_rec.id, 'suspended', null);
        action_taken := 'suspended'; subscription_id := v_rec.id; return next;
      else
        action_taken := 'dunning_attempt'; subscription_id := v_rec.id; return next;
      end if;
    end if;
  end loop;
  return;
end; $function$
;
CREATE OR REPLACE FUNCTION public.process_payment_rpc(p_center_id uuid, p_invoice_id uuid, p_amount numeric, p_payment_method text DEFAULT 'paymob'::text, p_recorded_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invoice     RECORD;
  v_center      RECORD;
  v_payment_id  UUID;
BEGIN
  SELECT * INTO v_invoice
  FROM invoices
  WHERE id = p_invoice_id AND center_id = p_center_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0001';
  END IF;

  IF v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'invoice_already_paid' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO payments (
    center_id, amount, method, paid_at, recorded_by
  )
  VALUES (
    p_center_id, p_amount, p_payment_method, NOW(), p_recorded_by
  )
  RETURNING id INTO v_payment_id;

  UPDATE invoices
  SET status = 'paid', paid_at = NOW()
  WHERE id = p_invoice_id;

  SELECT * INTO v_center FROM centers WHERE id = p_center_id FOR UPDATE;

  UPDATE centers
  SET
    billing_status   = 'paid',
    next_payment_due = CASE
      WHEN v_center.billing_cycle = 'monthly'
        THEN (v_center.next_payment_due + INTERVAL '1 month')::date
      WHEN v_center.billing_cycle = 'annual'
        THEN (v_center.next_payment_due + INTERVAL '1 year')::date
      ELSE
        (v_center.next_payment_due + INTERVAL '3 months')::date
    END
  WHERE id = p_center_id;

  INSERT INTO center_metrics_daily (
    center_id, metric_date,
    payments_recorded, last_payment_at, last_upserted_at
  )
  VALUES (
    p_center_id, CURRENT_DATE, 1, NOW(), NOW()
  )
  ON CONFLICT (center_id, metric_date) DO UPDATE SET
    payments_recorded = center_metrics_daily.payments_recorded + 1,
    last_payment_at   = NOW(),
    last_upserted_at  = NOW();

  RETURN jsonb_build_object(
    'success',    true,
    'payment_id', v_payment_id,
    'invoice_id', p_invoice_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.propose_group_slot(p_group_id uuid, p_actor_user_id uuid, p_day_of_week smallint, p_start_time time without time zone, p_end_time time without time zone, p_room_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS group_slot_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group public.student_groups%rowtype;
  v_row   public.group_slot_proposals%rowtype;
  v_dow   text;
begin
  select * into v_group from public.student_groups where id = p_group_id for update;
  if not found then
    raise exception 'group % not found', p_group_id using errcode = 'P0002';
  end if;
  if v_group.teacher_id is distinct from p_actor_user_id then
    raise exception 'group % not found', p_group_id using errcode = 'P0002';
  end if;
  if v_group.kind <> 'center' or v_group.center_id is null then
    raise exception 'group % is not center-attached', p_group_id using errcode = '23514';
  end if;
  if p_day_of_week is null or p_day_of_week < 0 or p_day_of_week > 6 then
    raise exception 'invalid day_of_week' using errcode = '22023';
  end if;
  if p_end_time <= p_start_time then
    raise exception 'end_time must be after start_time' using errcode = '22023';
  end if;
  if p_room_id is not null then
    perform 1 from public.rooms where id = p_room_id and center_id = v_group.center_id;
    if not found then
      raise exception 'room % not in this center', p_room_id using errcode = '23514';
    end if;
  end if;

  v_dow := p_day_of_week::text;
  if p_room_id is not null then
    perform 1 from public.schedule_slots s
      where s.center_id = v_group.center_id
        and s.room_id = p_room_id
        and s.day_of_week = v_dow
        and s.start_time < p_end_time
        and s.end_time   > p_start_time;
    if found then
      raise exception 'room is already booked at this time' using errcode = '23P01';
    end if;
  end if;
  if v_group.teacher_id is not null then
    perform 1 from public.schedule_slots s
      where s.teacher_id = v_group.teacher_id
        and s.day_of_week = v_dow
        and s.start_time < p_end_time
        and s.end_time   > p_start_time;
    if found then
      raise exception 'teacher is already booked at this time' using errcode = '23P01';
    end if;
  end if;

  update public.group_slot_proposals
     set status = 'withdrawn', updated_at = now()
   where group_id = p_group_id and status = 'pending';

  insert into public.group_slot_proposals
    (group_id, proposed_by, day_of_week, start_time, end_time, room_id, note)
  values
    (p_group_id, p_actor_user_id, p_day_of_week, p_start_time, p_end_time, p_room_id, p_note)
  returning * into v_row;

  return v_row;
end $function$
;
CREATE OR REPLACE FUNCTION public.provision_teacher_subscription_on_first_private_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan jsonb;
  v_trial_days int;
begin
  if new.kind <> 'private' or new.teacher_id is null then
    return new;
  end if;

  -- Already has a subscription row? do nothing (idempotent across 2nd/3rd group).
  if exists (select 1 from public.teacher_subscriptions ts where ts.teacher_id = new.teacher_id) then
    return new;
  end if;

  select value into v_plan from public.platform_config where key = 'teacher_subscription_plan';
  if v_plan is null then
    raise exception 'teacher_subscription_plan config missing; cannot provision subscription';
  end if;
  v_trial_days := coalesce((v_plan->>'trial_days')::int, 14);

  insert into public.teacher_subscriptions
    (teacher_id, plan_key, status, trial_ends_at, current_period_start, current_period_end,
     price_gross, price_net, snap_vat_amount, next_billing_at)
  values (
    new.teacher_id,
    v_plan->>'plan_key',
    'trialing',
    now() + make_interval(days => v_trial_days),
    now(),
    now() + make_interval(days => v_trial_days),
    (v_plan->>'price_gross')::numeric,
    (v_plan->>'price_net')::numeric,
    (v_plan->>'vat_amount')::numeric,
    now() + make_interval(days => v_trial_days)
  );

  insert into public.audit_log (action, entity_type, entity_id, user_id, details)
  values ('teacher_subscription_provisioned','teacher_subscription', new.teacher_id, new.teacher_id,
          jsonb_build_object('trigger_group_id', new.id, 'trial_days', v_trial_days));

  return new;
end; $function$
;
CREATE OR REPLACE FUNCTION public.recalc_all_lifecycle_status()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT id FROM students LOOP
    PERFORM recalc_student_lifecycle(r.id);
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.recalc_student_lifecycle(p_student_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_center_id UUID;
  v_last_scan TIMESTAMPTZ;
  v_scans_14d INT;
  v_expected_14d INT;
  v_rate NUMERIC;
  v_new_status TEXT;
  v_old_status TEXT;
  v_at_risk_since TIMESTAMPTZ;
BEGIN
  SELECT center_id, lifecycle_status, at_risk_since INTO v_center_id, v_old_status, v_at_risk_since
  FROM students WHERE id = p_student_id;
  IF v_center_id IS NULL THEN RETURN; END IF;

  -- Last scan
  SELECT MAX(scanned_at) INTO v_last_scan
  FROM attendance_scans WHERE student_id = p_student_id AND center_id = v_center_id;

  -- No scan in 30 days → inactive
  IF v_last_scan IS NULL OR v_last_scan < (now() - interval '30 days') THEN
    v_new_status := 'inactive';
    IF v_old_status IS DISTINCT FROM v_new_status THEN
      UPDATE students SET lifecycle_status = v_new_status, last_status_change = now(), at_risk_since = NULL
      WHERE id = p_student_id;
    END IF;
    RETURN;
  END IF;

  -- Scans in last 14 days vs expected (approx 2 sessions/week per group)
  SELECT COUNT(*) INTO v_scans_14d
  FROM attendance_scans
  WHERE student_id = p_student_id AND center_id = v_center_id
    AND scanned_at >= (now() - interval '14 days');

  SELECT COALESCE(SUM(2), 0) INTO v_expected_14d
  FROM student_group_members sgm
  JOIN student_groups sg ON sg.id = sgm.group_id AND sg.center_id = v_center_id
  WHERE sgm.student_id = p_student_id;

  v_expected_14d := GREATEST(v_expected_14d, 1);
  v_rate := (v_scans_14d::NUMERIC / v_expected_14d) * 100;

  -- Below 60% for 14 days → at_risk
  IF v_rate < 60 THEN
    v_new_status := 'at_risk';
    IF v_old_status IS DISTINCT FROM v_new_status THEN
      UPDATE students SET
        lifecycle_status = v_new_status,
        last_status_change = now(),
        at_risk_since = COALESCE(at_risk_since, now())
      WHERE id = p_student_id;
    ELSIF v_old_status = 'at_risk' AND v_at_risk_since IS NULL THEN
      UPDATE students SET at_risk_since = now() WHERE id = p_student_id;
    END IF;
    RETURN;
  END IF;

  -- Above 70% → active
  IF v_rate >= 70 THEN
    v_new_status := 'active';
    IF v_old_status IN ('at_risk', 'enrolled') AND v_old_status IS DISTINCT FROM v_new_status THEN
      UPDATE students SET lifecycle_status = v_new_status, last_status_change = now(), at_risk_since = NULL
      WHERE id = p_student_id;
    END IF;
    RETURN;
  END IF;

  -- Between 60-70%: keep current (at_risk stays, active stays)
  NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.recompute_all_health_scores()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  sc INT;
  cnt INT := 0;
BEGIN
  FOR r IN SELECT id FROM centers WHERE status = 'active'
  LOOP
    sc := compute_center_health_score(r.id);
    UPDATE centers
    SET health_score = sc,
        health_score_band = CASE
          WHEN sc >= 80 THEN 'Healthy'
          WHEN sc >= 60 THEN 'Engaged'
          WHEN sc >= 40 THEN 'At Risk'
          ELSE 'Critical'
        END
    WHERE id = r.id;
    cnt := cnt + 1;
  END LOOP;
  RETURN cnt;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.record_subscription_payment(p_subscription_id uuid, p_provider_ref text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS teacher_subscriptions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sub public.teacher_subscriptions;
  v_free int;
begin
  select * into v_sub from public.teacher_subscriptions where id = p_subscription_id for update;
  if not found then raise exception 'subscription % not found', p_subscription_id using errcode='P0002'; end if;

  -- Move to active via the guarded transition (handles trialing/past_due/suspended -> active).
  if v_sub.status <> 'active' then
    perform public.apply_teacher_subscription_transition(p_subscription_id, 'active', p_actor_id);
  end if;

  v_free := v_sub.free_months_credit;

  -- Roll the period one month forward, reset dunning, stamp payment.
  update public.teacher_subscriptions
  set current_period_start = now(),
      current_period_end   = now() + interval '1 month',
      next_billing_at      = now() + interval '1 month',
      last_payment_at      = now(),
      dunning_attempts     = 0,
      grace_until          = null,
      provider_ref         = coalesce(p_provider_ref, provider_ref),
      free_months_credit   = greatest(v_free - case when v_free > 0 then 1 else 0 end, 0)
  where id = p_subscription_id
  returning * into v_sub;

  insert into public.audit_log (action, entity_type, entity_id, user_id, details)
  values ('subscription_payment_recorded','teacher_subscription',p_subscription_id,p_actor_id,
          jsonb_build_object('provider_ref',p_provider_ref,'free_month_consumed', v_free > 0,
                             'period_end', v_sub.current_period_end));
  return v_sub;
end; $function$
;
CREATE OR REPLACE FUNCTION public.redeem_promo_code(p_code_id uuid, p_user_id uuid, p_center_id uuid, p_paymob_order_id text, p_original_amount_egp integer, p_discount_amount_egp integer)
 RETURNS TABLE(redemption_id uuid, discount_pct integer, uses_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_redemption_id UUID;
  v_pct INTEGER;
  v_uses INTEGER;
BEGIN
  -- Atomic check + increment.
  UPDATE promo_codes
     SET uses_count = uses_count + 1
   WHERE id = p_code_id
     AND is_active = true
     AND (expires_at IS NULL OR expires_at > now())
     AND (max_uses_total IS NULL OR uses_count < max_uses_total)
  RETURNING promo_codes.discount_pct, promo_codes.uses_count
       INTO v_pct, v_uses;

  IF NOT FOUND THEN
    -- Code is inactive, expired, or exhausted. Deny redemption.
    RETURN;
  END IF;

  -- Per-centre idempotency: UNIQUE(promo_code_id, center_id) on
  -- promo_code_redemptions. If a redemption already exists for this centre,
  -- ON CONFLICT DO NOTHING + the rollback below keep uses_count consistent.
  INSERT INTO promo_code_redemptions (
    promo_code_id, user_id, center_id, paymob_order_id,
    original_amount_egp, discount_amount_egp
  ) VALUES (
    p_code_id, p_user_id, p_center_id, p_paymob_order_id,
    p_original_amount_egp, p_discount_amount_egp
  )
  ON CONFLICT (promo_code_id, center_id) DO NOTHING
  RETURNING id INTO v_redemption_id;

  IF v_redemption_id IS NULL THEN
    -- Already redeemed by this centre. Roll the increment back so
    -- uses_count reflects unique-centre redemptions only.
    UPDATE promo_codes
       SET uses_count = uses_count - 1
     WHERE id = p_code_id;
    RETURN;
  END IF;

  RETURN QUERY SELECT v_redemption_id, v_pct, v_uses;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.remove_teacher_from_center(p_teacher_user_id uuid, p_center_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS teacher_center
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_tc public.teacher_center; v_cleared int;
begin
  select * into v_tc from public.teacher_center
   where teacher_id=p_teacher_user_id and center_id=p_center_id for update;
  if not found then raise exception 'no relationship for teacher % at center %', p_teacher_user_id, p_center_id using errcode='P0002'; end if;

  update public.teacher_center set status='inactive' where id=v_tc.id returning * into v_tc;

  -- Clear the teacher from this center's groups (groups become unassigned).
  update public.student_groups
    set teacher_id=null
    where center_id=p_center_id and teacher_id=p_teacher_user_id and kind='center';
  get diagnostics v_cleared = row_count;

  insert into public.audit_log (action, entity_type, entity_id, user_id, center_id, details)
  values ('teacher_removed_from_center','teacher_center', v_tc.id, p_actor_id, p_center_id,
          jsonb_build_object('teacher_id', p_teacher_user_id, 'groups_unassigned', v_cleared));
  return v_tc;
end; $function$
;
CREATE OR REPLACE FUNCTION public.reserve_credits_atomic(p_center_id uuid, p_amount numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_available NUMERIC;
BEGIN
  SELECT credit_balance - COALESCE(credit_reserved, 0)
  INTO v_available
  FROM centers WHERE id = p_center_id FOR UPDATE;

  IF v_available < p_amount THEN
    RETURN FALSE;
  END IF;

  UPDATE centers
  SET credit_reserved = COALESCE(credit_reserved, 0) + p_amount
  WHERE id = p_center_id;

  RETURN TRUE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reset_subscription_blast_credits(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_plan_key text;
begin
  select plan_key into v_plan_key from public.teacher_profiles where user_id=p_user_id for update;
  if not found then raise exception 'no teacher profile for %', p_user_id using errcode='P0002'; end if;
  if v_plan_key not in ('teacher_pro','teacher_scale') then
    return jsonb_build_object('reset', false, 'reason', 'not_pro');
  end if;
  update public.teacher_profiles set blast_credits_subscription=100 where user_id=p_user_id;
  insert into public.audit_log (action,entity_type,entity_id,user_id,center_id,details)
  values ('teacher_blast_credits_reset','teacher_profile',p_user_id,p_user_id,null,
          jsonb_build_object('blast_credits_subscription',100));
  return jsonb_build_object('reset', true);
end; $function$
;
CREATE OR REPLACE FUNCTION public.resolve_inactivity_alerts_on_scan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE wa_inactivity_alerts
  SET resolved_at = now()
  WHERE center_id = NEW.center_id
    AND resolved_at IS NULL;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_or_create_student(p_name text, p_phone text, p_center_id uuid DEFAULT NULL::uuid, p_parent_phone text DEFAULT NULL::text, p_grade_level text DEFAULT NULL::text, p_origin text DEFAULT 'self_link'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
begin
  if p_phone is null or length(trim(p_phone)) = 0 then
    raise exception 'student phone required for resolution' using errcode='23514';
  end if;
  if p_origin not in ('self_link','walk_in','inherited','import') then
    raise exception 'invalid origin %', p_origin using errcode='23514';
  end if;

  -- Match on the student's OWN phone, scoped to center. Sibling-safe (siblings share
  -- parent_phone but have distinct own phones). Active rows only (is_active).
  select id into v_id from public.students
   where phone = p_phone
     and ((p_center_id is null and center_id is null) or center_id = p_center_id)
     and coalesce(is_active, true) = true
   limit 1;

  if v_id is not null then
    return v_id;
  end if;

  insert into public.students (name, phone, parent_phone, center_id, grade_level, origin, is_active)
  values (p_name, p_phone, p_parent_phone, p_center_id, p_grade_level, p_origin, true)
  returning id into v_id;

  return v_id;
end; $function$
;
CREATE OR REPLACE FUNCTION public.respond_center_group_proposal(p_proposal_id uuid, p_actor_user_id uuid, p_action text, p_cut_egp numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS TABLE(proposal_status text, group_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prop public.group_proposals%rowtype;
  v_status text;
  v_group_id uuid;
begin
  if p_action not in ('accept','counter','decline') then
    raise exception 'invalid action %', p_action using errcode = '22023';
  end if;

  select * into v_prop from public.group_proposals where id = p_proposal_id for update;
  if not found then
    raise exception 'proposal % not found', p_proposal_id using errcode = 'P0002';
  end if;
  if v_prop.teacher_id <> p_actor_user_id then
    raise exception 'proposal % not found', p_proposal_id using errcode = 'P0002';
  end if;
  if v_prop.initiated_by <> 'center' or coalesce(v_prop.carries_link, false) = false then
    raise exception 'proposal % does not carry a pending link', p_proposal_id using errcode = '23514';
  end if;
  if v_prop.status <> 'open' then
    raise exception 'proposal is not open (status %)', v_prop.status using errcode = '23514';
  end if;

  if p_action = 'decline' then
    delete from public.teacher_center
      where teacher_id = v_prop.teacher_id
        and center_id  = v_prop.center_id
        and status = 'pending';

    select pr.proposal_status, pr.group_id into v_status, v_group_id
      from public.respond_group_proposal(
        p_proposal_id, p_actor_user_id, 'teacher', 'decline', null, null) as pr;
    return query select v_status, v_group_id;
    return;
  end if;

  update public.teacher_center
     set status = 'active', accepted_at = now()
   where teacher_id = v_prop.teacher_id
     and center_id  = v_prop.center_id
     and status = 'pending';
  if not exists (
    select 1 from public.teacher_center
     where teacher_id = v_prop.teacher_id and center_id = v_prop.center_id
  ) then
    insert into public.teacher_center (teacher_id, center_id, status, accepted_at)
    values (v_prop.teacher_id, v_prop.center_id, 'active', now());
  end if;

  update public.group_proposals
     set carries_link = false, updated_at = now()
   where id = p_proposal_id;

  select pr.proposal_status, pr.group_id into v_status, v_group_id
    from public.respond_group_proposal(
      p_proposal_id, p_actor_user_id, 'teacher', p_action, p_cut_egp, p_note) as pr;
  return query select v_status, v_group_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.respond_group_proposal(p_proposal_id uuid, p_actor_user_id uuid, p_side text, p_action text, p_cut_egp numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS TABLE(proposal_status text, group_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prop public.group_proposals%rowtype;
  v_latest public.group_proposal_offers%rowtype;
  v_group public.student_groups%rowtype;
  v_group_id uuid;
  v_name text;
begin
  if p_side not in ('teacher','center') then
    raise exception 'invalid side %', p_side using errcode = '22023';
  end if;
  if p_action not in ('accept','counter','decline','withdraw') then
    raise exception 'invalid action %', p_action using errcode = '22023';
  end if;

  select * into v_prop from public.group_proposals where id = p_proposal_id for update;
  if not found then
    raise exception 'proposal % not found', p_proposal_id using errcode = 'P0002';
  end if;
  if v_prop.status <> 'open' then
    raise exception 'proposal is not open (status %)', v_prop.status using errcode = '23514';
  end if;

  select * into v_latest
    from public.group_proposal_offers
   where proposal_id = p_proposal_id
   order by created_at desc, id desc
   limit 1;
  if not found then
    raise exception 'proposal % has no offers', p_proposal_id using errcode = '23514';
  end if;

  if p_action = 'withdraw' then
    if v_latest.made_by <> p_side then
      raise exception 'can only withdraw your own standing offer' using errcode = '23514';
    end if;
    update public.group_proposals
       set status = 'withdrawn', responded_by = p_actor_user_id, responded_at = now(), updated_at = now()
     where id = p_proposal_id;
    return query select 'withdrawn'::text, null::uuid;
    return;
  end if;

  if p_action = 'decline' then
    if v_latest.made_by = p_side then
      raise exception 'not your turn: latest offer was made by %', v_latest.made_by using errcode = '23514';
    end if;
    update public.group_proposals
       set status = 'declined', responded_by = p_actor_user_id, responded_at = now(), updated_at = now()
     where id = p_proposal_id;
    return query select 'declined'::text, null::uuid;
    return;
  end if;

  if v_latest.made_by = p_side then
    raise exception 'not your turn: latest offer was made by %', v_latest.made_by using errcode = '23514';
  end if;

  if p_action = 'counter' then
    if p_cut_egp is null then
      raise exception 'counter requires cut_egp' using errcode = '22023';
    end if;
    insert into public.group_proposal_offers (proposal_id, made_by, cut_egp, note)
    values (p_proposal_id, p_side, p_cut_egp, p_note);
    return query select 'open'::text, null::uuid;
    return;
  end if;

  update public.group_proposals
     set status = 'accepted', accepted_offer_id = v_latest.id,
         responded_by = p_actor_user_id, responded_at = now(), updated_at = now()
   where id = p_proposal_id;

  if v_prop.target_group_id is not null then
    select * into v_group from public.student_groups
      where id = v_prop.target_group_id for update;
    if not found then
      raise exception 'target group % not found', v_prop.target_group_id using errcode = 'P0002';
    end if;

    if v_group.kind = 'center' then
      if v_group.center_id <> v_prop.center_id then
        raise exception 'target group % does not belong to center %',
          v_prop.target_group_id, v_prop.center_id using errcode = '23514';
      end if;
      if v_group.teacher_id is not null then
        raise exception 'target group % already has a teacher', v_prop.target_group_id using errcode = '23514';
      end if;

      update public.student_groups
         set teacher_id = v_prop.teacher_id, center_cut_egp = v_latest.cut_egp
       where id = v_prop.target_group_id;

      return query select 'accepted'::text, v_prop.target_group_id;
      return;

    elsif v_group.kind = 'private'
          and v_group.teacher_id = v_prop.teacher_id
          and v_group.center_id is null then
      update public.student_groups
         set center_id = v_prop.center_id,
             center_cut_egp = v_latest.cut_egp,
             kind = 'center'
       where id = v_prop.target_group_id;

      return query select 'accepted'::text, v_prop.target_group_id;
      return;

    else
      raise exception 'target group % is not attachable', v_prop.target_group_id using errcode = '23514';
    end if;
  end if;

  v_name := v_prop.subject || case when v_prop.grade_level is not null and v_prop.grade_level <> ''
                                   then ' - ' || v_prop.grade_level else '' end;

  insert into public.student_groups
    (center_id, teacher_id, kind, name, subject, fee_per_class, center_cut_egp, status)
  values
    (v_prop.center_id, v_prop.teacher_id, 'center', v_name, v_prop.subject,
     v_prop.fee_per_class, v_latest.cut_egp, 'active')
  returning id into v_group_id;

  return query select 'accepted'::text, v_group_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.respond_teacher_code_group_proposal(p_proposal_id uuid, p_center_id uuid, p_actor_user_id uuid, p_action text, p_cut_egp numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS TABLE(proposal_status text, group_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prop public.group_proposals%rowtype;
  v_status text;
  v_group_id uuid;
begin
  if p_action not in ('accept','counter','decline') then
    raise exception 'invalid action %', p_action using errcode = '22023';
  end if;

  select * into v_prop from public.group_proposals where id = p_proposal_id for update;
  if not found then
    raise exception 'proposal % not found', p_proposal_id using errcode = 'P0002';
  end if;
  if v_prop.center_id is distinct from p_center_id then
    raise exception 'proposal % not found', p_proposal_id using errcode = 'P0002';
  end if;
  if v_prop.initiated_by <> 'teacher' or coalesce(v_prop.carries_link, false) = false then
    raise exception 'proposal % does not carry a pending link', p_proposal_id using errcode = '23514';
  end if;
  if v_prop.status <> 'open' then
    raise exception 'proposal is not open (status %)', v_prop.status using errcode = '23514';
  end if;

  if p_action = 'decline' then
    delete from public.teacher_center
      where teacher_id = v_prop.teacher_id
        and center_id  = v_prop.center_id
        and status = 'pending';

    select pr.proposal_status, pr.group_id into v_status, v_group_id
      from public.respond_group_proposal(
        p_proposal_id, p_actor_user_id, 'center', 'decline', null, null) as pr;
    return query select v_status, v_group_id;
    return;
  end if;

  update public.teacher_center
     set status = 'active', accepted_at = now()
   where teacher_id = v_prop.teacher_id
     and center_id  = v_prop.center_id
     and status = 'pending';
  if not exists (
    select 1 from public.teacher_center
     where teacher_id = v_prop.teacher_id and center_id = v_prop.center_id
  ) then
    insert into public.teacher_center (teacher_id, center_id, status, invited_by, accepted_at)
    values (v_prop.teacher_id, v_prop.center_id, 'active', p_actor_user_id, now());
  end if;

  update public.group_proposals
     set carries_link = false, updated_at = now()
   where id = p_proposal_id;

  select pr.proposal_status, pr.group_id into v_status, v_group_id
    from public.respond_group_proposal(
      p_proposal_id, p_actor_user_id, 'center', p_action, p_cut_egp, p_note) as pr;
  return query select v_status, v_group_id;
end $function$
;
