CREATE OR REPLACE FUNCTION public.upsert_scan_metric(p_center_id uuid, p_scanned_at timestamp with time zone, p_metric_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.center_metrics_daily AS cmd (
    center_id,
    metric_date,
    total_scans,
    last_scan_at,
    last_upserted_at
  )
  VALUES (
    p_center_id,
    p_metric_date,
    1,
    p_scanned_at,
    now()
  )
  ON CONFLICT (center_id, metric_date)
  DO UPDATE SET
    total_scans = COALESCE(cmd.total_scans, 0) + 1,
    last_scan_at = CASE
      WHEN cmd.last_scan_at IS NULL THEN p_scanned_at
      WHEN p_scanned_at > cmd.last_scan_at THEN p_scanned_at
      ELSE cmd.last_scan_at
    END,
    last_upserted_at = now();
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_reports_to()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.reports_to IS NOT NULL THEN
    IF NEW.id = NEW.reports_to THEN
      RAISE EXCEPTION 'Staff member cannot report to themselves';
    END IF;
    IF NEW.role = 'sm' THEN
      RAISE EXCEPTION 'SM reports to Eyad directly — do not set reports_to for SM role';
    END IF;
    IF (SELECT role FROM staff WHERE id = NEW.reports_to) != 'sm' THEN
      RAISE EXCEPTION 'SR must report to an SM, not another SR';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

