-- ---------- triggers ----------
CREATE TRIGGER trg_chq_prevent_blast_tampering BEFORE UPDATE ON public.announcement_blasts FOR EACH ROW WHEN ((auth.uid() IS NOT NULL)) EXECUTE FUNCTION chq_prevent_blast_tampering();
CREATE TRIGGER trg_recalc_lifecycle_on_scan AFTER INSERT ON public.attendance_scans FOR EACH ROW EXECUTE FUNCTION trigger_recalc_lifecycle_on_scan();
CREATE TRIGGER trigger_resolve_inactivity_on_scan AFTER INSERT ON public.attendance_scans FOR EACH ROW EXECUTE FUNCTION resolve_inactivity_alerts_on_scan();
CREATE TRIGGER audit_log_no_update_delete BEFORE DELETE OR UPDATE ON public.audit_log FOR EACH ROW EXECUTE FUNCTION audit_log_block_mutations();
CREATE TRIGGER trg_card_charge_intents_updated_at BEFORE UPDATE ON public.card_charge_intents FOR EACH ROW EXECUTE FUNCTION set_saved_card_updated_at();
CREATE TRIGGER card_order_cart_items_bump_parent AFTER INSERT OR DELETE OR UPDATE ON public.card_order_cart_items FOR EACH ROW EXECUTE FUNCTION bump_cart_on_item_change();
CREATE TRIGGER card_order_carts_set_updated_at BEFORE UPDATE ON public.card_order_carts FOR EACH ROW EXECUTE FUNCTION set_updated_at_now();
CREATE TRIGGER card_orders_log_status_transition AFTER UPDATE OF status ON public.card_orders FOR EACH ROW EXECUTE FUNCTION log_card_order_status_transition();
CREATE TRIGGER trg_chq_prevent_card_order_tampering BEFORE UPDATE ON public.card_orders FOR EACH ROW WHEN ((auth.uid() IS NOT NULL)) EXECUTE FUNCTION chq_prevent_card_order_tampering();
CREATE TRIGGER center_notes_updated_at BEFORE UPDATE ON public.center_notes FOR EACH ROW EXECUTE FUNCTION set_center_notes_updated_at();
CREATE TRIGGER auto_assign_center_code BEFORE INSERT ON public.centers FOR EACH ROW WHEN ((new.center_code IS NULL)) EXECUTE FUNCTION assign_center_code();
CREATE TRIGGER set_referral_code BEFORE INSERT ON public.centers FOR EACH ROW WHEN (((new.referral_code IS NULL) OR (length(COALESCE(TRIM(BOTH FROM new.referral_code), ''::text)) <> 8))) EXECUTE FUNCTION generate_referral_code_8char();
CREATE TRIGGER trg_chq_prevent_center_escalation BEFORE UPDATE ON public.centers FOR EACH ROW WHEN ((auth.uid() IS NOT NULL)) EXECUTE FUNCTION chq_prevent_center_escalation();
CREATE TRIGGER trigger_update_billing_amount BEFORE INSERT OR UPDATE OF plan, billing_period, billing_cycle_start ON public.centers FOR EACH ROW EXECUTE FUNCTION update_billing_amount();
CREATE TRIGGER ceo_action_queue_updated_at BEFORE UPDATE ON public.ceo_action_queue FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER payout_status_guard BEFORE UPDATE ON public.commission_payouts FOR EACH ROW EXECUTE FUNCTION enforce_payout_status_transition();
CREATE TRIGGER trg_demo_requests_updated_at BEFORE UPDATE ON public.demo_requests FOR EACH ROW EXECUTE FUNCTION set_demo_requests_updated_at();
CREATE TRIGGER trg_guard_enrollments_lifecycle BEFORE UPDATE ON public.enrollments FOR EACH ROW EXECUTE FUNCTION guard_enrollments_lifecycle();
CREATE TRIGGER trg_group_proposal_offers_append_only BEFORE DELETE OR UPDATE ON public.group_proposal_offers FOR EACH ROW EXECUTE FUNCTION block_group_proposal_offer_mutation();
CREATE TRIGGER trg_guard_group_proposal_offer BEFORE INSERT ON public.group_proposal_offers FOR EACH ROW EXECUTE FUNCTION guard_group_proposal_offer();
CREATE TRIGGER set_updated_at_group_proposals BEFORE UPDATE ON public.group_proposals FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_guard_group_proposals_update BEFORE UPDATE ON public.group_proposals FOR EACH ROW EXECUTE FUNCTION guard_group_proposals_update();
CREATE TRIGGER set_invoice_number BEFORE INSERT ON public.invoices FOR EACH ROW WHEN ((new.invoice_number IS NULL)) EXECUTE FUNCTION generate_invoice_number();
CREATE TRIGGER trg_chq_prevent_invoice_tampering BEFORE UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION chq_prevent_invoice_tampering();
CREATE TRIGGER pack_requests_touch_updated BEFORE UPDATE ON public.pack_requests FOR EACH ROW EXECUTE FUNCTION touch_pack_requests_updated_at();
