CREATE POLICY assessment_scores_insert ON public.assessment_scores AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK ((EXISTS ( SELECT 1
   FROM assessments a
  WHERE ((a.id = assessment_scores.assessment_id) AND (((a.group_id = ANY (get_auth_teacher_group_ids())) AND (NOT is_auth_teacher_suspended())) OR ((a.group_id = ANY (get_auth_center_group_ids())) AND has_center_role(ARRAY['owner'::text, 'admin'::text])))))));
CREATE POLICY assessment_scores_select ON public.assessment_scores AS PERMISSIVE FOR SELECT TO PUBLIC USING ((EXISTS ( SELECT 1
   FROM assessments a
  WHERE (a.id = assessment_scores.assessment_id))));
