CREATE POLICY assessments_insert ON public.assessments AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK ((((group_id = ANY (get_auth_teacher_group_ids())) AND (NOT is_auth_teacher_suspended())) OR ((group_id = ANY (get_auth_center_group_ids())) AND has_center_role(ARRAY['owner'::text, 'admin'::text]))));
CREATE POLICY assessments_select ON public.assessments AS PERMISSIVE FOR SELECT TO PUBLIC USING (((group_id = ANY (get_auth_teacher_group_ids())) OR (group_id = ANY (get_auth_center_group_ids()))));
CREATE POLICY assessments_update ON public.assessments AS PERMISSIVE FOR UPDATE TO PUBLIC USING ((((group_id = ANY (get_auth_teacher_group_ids())) AND (NOT is_auth_teacher_suspended())) OR ((group_id = ANY (get_auth_center_group_ids())) AND has_center_role(ARRAY['owner'::text, 'admin'::text])))) WITH CHECK ((((group_id = ANY (get_auth_teacher_group_ids())) AND (NOT is_auth_teacher_suspended())) OR ((group_id = ANY (get_auth_center_group_ids())) AND has_center_role(ARRAY['owner'::text, 'admin'::text]))));
