-- ---------- storage.objects policies (guarded) ----------
DO $$ BEGIN IF to_regclass('storage.objects') IS NOT NULL THEN EXECUTE 'CREATE POLICY "Authenticated users can update logos" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING ((bucket_id = ''center-logos''::text))'; END IF; END $$;
DO $$ BEGIN IF to_regclass('storage.objects') IS NOT NULL THEN EXECUTE 'CREATE POLICY "Authenticated users can upload logos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = ''center-logos''::text))'; END IF; END $$;
DO $$ BEGIN IF to_regclass('storage.objects') IS NOT NULL THEN EXECUTE 'CREATE POLICY invoice_pdfs_authenticated_select_own_center ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = ''invoice-pdfs''::text) AND ((storage.foldername(name))[1] = ''invoices''::text) AND ((storage.foldername(name))[2] IN ( SELECT (u.center_id)::text AS center_id
   FROM users u
  WHERE ((u.id = auth.uid()) AND (u.center_id IS NOT NULL))))))'; END IF; END $$;
DO $$ BEGIN IF to_regclass('storage.objects') IS NOT NULL THEN EXECUTE 'CREATE POLICY invoice_pdfs_service_role_all ON storage.objects AS PERMISSIVE FOR ALL TO service_role USING ((bucket_id = ''invoice-pdfs''::text)) WITH CHECK ((bucket_id = ''invoice-pdfs''::text))'; END IF; END $$;
DO $$ BEGIN IF to_regclass('storage.objects') IS NOT NULL THEN EXECUTE 'CREATE POLICY service_role_pdf_all ON storage.objects AS PERMISSIVE FOR ALL TO public USING ((bucket_id = ''card-order-pdfs''::text)) WITH CHECK ((bucket_id = ''card-order-pdfs''::text))'; END IF; END $$;